programs.sol:
"""Recognise live/life spellings, including roots split across tokens.

Live and its verb forms get the strongest response; life, love, olive,
and the related liv-/lif-/viv- stems get weaker responses. Possessive
'lives' is weaker than the verb, and 'daily life' is stronger than life.
This is a spelling-sensitive approximation, not a general life-concept
detector. Chinese 生活 and Russian жив receive smaller responses.
The estimate also extends weakly into following in/on.
Two secondary cues are repeated middle dots and a document's Title colon.
"""
import re

READS = ()
# Whole-token and split-after-the-first-letter strengths for related words.
FAMILY = {
    'live': (6.8, 8.0),
    'lived': (7.1, 10.5),
    'lives': (7.0, 6.5),
    'living': (4.7, 10.0),
    'liveness': (7.0, 8.4),
    'lively': (1.1, 6.1),
    'liven': (6.0, 7.8),
    'life': (1.3, 5.4),
    'lif': (4.2, 5.0),
    'liv': (4.2, 7.6),
    'viv': (4.6, 6.3),
    'vive': (5.3, 4.7),
    'vivo': (6.4, 8.0),
    'viva': (4.0, 4.0),
    'liver': (2.3, 2.5),
    'lifetime': (3.1, 1.0),
    'lifelong': (2.9, 2.9),
    'lifestyle': (1.6, 2.3),
    'livelihood': (2.0, 2.0),
    'olive': (3.7, 3.7),
    'love': (0.5, 1.4),
    'loved': (0.5, 4.4),
    'loves': (1.6, 4.8),
    'loving': (0.5, 1.0),
}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their', 'own'}
SUBJECTS = {'i', 'we', 'you', 'they', 'he', 'she', 'it', 'who', 'which'}
MODALS = {'can', 'could', 'will', 'would', 'shall', 'should', 'must', 'may', 'might'}


def response(token, previous, tail):
    s = token.lower().strip()
    word = s.lstrip('-_')
    words = re.findall(r'[a-z]+', tail.lower())
    last = words[-1] if words else ''
    value = FAMILY.get(word, (0.0, 0.0))[0]
    if word == 'liv' and not token.startswith(' '):
        value = 5.6
    elif word == 'olive':
        value = 4.9 if token.strip().istitle() else 3.4
    elif word == 'lives':
        if last in POSSESSIVES:
            value = 3.0
        elif last in {'the', 'many', 'human', 'entire', 'daily'}:
            value = 4.6
        elif last in SUBJECTS:
            value = 11.0
    elif word == 'live':
        if last in SUBJECTS or last == 'to':
            value = 8.4
        elif last in MODALS:
            value = 9.5
        elif last in {'a', 'an', 'the', 'in'}:
            value = 6.0
        elif token.strip() != token.strip().lower():
            value = 6.5
        if not tail:
            value = 14.0
    elif word == 'living' and not token.startswith(' '):
        value = 6.2
    elif word == 'life' and last in {'daily', 'everyday', 'real', 'after', 'half'}:
        value = 4.7
    elif '生活' in token:
        value = 3.5
    elif word in {'жив', 'лив'}:
        value = 1.7
        if word == 'жив':
            value = 3.5 if token.startswith(' ') else 0.8

    # Recognise the same roots when tokenisation cuts through them.
    if token and token[0].isalpha():
        t = tail.lower()
        for initial in ('l', 'v'):
            completed = initial + s
            if t.endswith(initial) and completed in FAMILY:
                value = FAMILY[completed][1]
        if t.endswith(('l', 'v', 'ž')) and s.startswith('iv'):
            if s not in {
                'iv', 'ive', 'ives', 'ived', 'iving', 'iveness',
                'iven', 'iver', 'ivery'
            }:
                value = 4.8
            if t.endswith(('v', 'ž')) and s in {'iv', 'iver', 'ives', 'iven'}:
                value = 6.0
        if t.endswith('l') and s == 'if':
            isolated_l = previous.lower().strip().lstrip('/_-') == 'l'
            value = 7.0 if isolated_l else 3.0
        elif t.endswith('l') and s == 'ifer':
            value = 3.8
        elif t.endswith('liv') and s in {'able', 'eli', 'el', 'eliness', 'in'}:
            value = 4.8
        elif t.endswith('viv') and s in {
            'ir', 'ere', 'ent', 'iendo', 'ono', 'imos', 'iam', 'ido', 'ía', 'i'
        }:
            value = 5.5
        elif t.endswith('viv') and s == 're':
            value = 3.4
        elif t.endswith('lif') and s in {'el', 'eline'}:
            value = 4.3
        elif (previous.lower().strip() == 'ж'
              and s.startswith(('ив', 'ил', 'ить'))):
            value = 5.5
    if s in {'in', 'on'} and previous.lower().strip() in {
        'live', 'lives', 'living', 'lived'
    }:
        value += 1.0
    if len(token) > 1 and set(token) == {'·'}:
        value = 2.1
    if token == ':' and tail == 'Title':
        value = -8.96
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (doc, token, (tail + token)[-48:]), value

programs.haiku:
"""Detector for the verb "to live" and its forms, plus the related "viv-" and "life" words.

Layer 1, MLP down-projection component 5568 of Qwen3-1.7B. It writes a positive signal into the
residual stream on the word "live" (also lived, lives, living) when it is a verb meaning to reside
or to be alive. It is strongest after a subject, "to" or a modal ("we live", "to live", "who lives"),
medium elsewhere, and weakest after a determiner ("the live sperms", "their living"), where "live"
is an adjective or noun. Weaker still on Romance "viv-" words (vivo, vive, viv, vivir), on "liv"
and "olive", on Russian жив, on 生活, and on "life" words. Every other token gets 0.
The program reads the current token and the one before it: a stateless lookup.
"""

READS = ()

LIVE_FORMS = {"live", "lived", "lives", "living"}
DETERMINERS = {"the", "a", "an", "their", "our", "your", "my", "his", "her", "its", "of", "some", "those"}
SUBJECTS = {"to", "will", "we", "you", "i", "they", "who", "he", "she", "can", "must", "would", "should"}
VIVE_FORMS = {"vivo", "vive", "viv", "vida", "vivir", "viver", "vivía", "vivi"}
WEAK_FORMS = {"liv", "lif", "olive", "жив", "лив", "生活"}
LIFE_FORMS = {"life", "lifetime", "lifestyle", "lifelong"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in LIVE_FORMS:
        before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
        if before in SUBJECTS:
            value = 8.5
        elif before in DETERMINERS:
            value = 4.5
        else:
            value = 6.5
    elif word in VIVE_FORMS:
        value = 4.5
    elif word in WEAK_FORMS:
        value = 3.0
    elif word in LIFE_FORMS:
        value = 1.5
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Sparse spelling cues, including cues split between adjacent tokens.

The strongest negative cue is a dismiss-, seiz-, or seism- spelling.
Smaller cues distinguish s/z continuations from several 'ei' spellings.
The previous word also matters for 'of' after dismissal or seizure.
There are also small cues for French sais- spellings, doubled middle dots,
and a document-initial 'Title:' marker. Most other tokens stay near zero.
Non-Latin spellings and most small context effects are not modeled.
"""
import re

READS = ()
LETTERS_AT_END = re.compile(r'[A-Za-z]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, old_word, age = '', '', 0
    else:
        _, previous, old_word, age = carry

    tail = LETTERS_AT_END.search(s)
    word = tail.group() if tail else ''
    continued = bool(s and s.isascii() and s.isalpha() and old_word)
    if continued:
        word = (old_word + s)[-64:]
    w, old = word.lower(), old_word.lower()
    current = s.strip().lower()
    p = previous.lower().strip()
    value = 0.001

    if w.startswith('dismiss'):
        value = -9.0 if w.endswith('al') else -7.2
        if w.endswith('ing'):
            value = -6.0
        elif w.endswith('ed'):
            value = -7.5
        if old.startswith('dismiss') and continued:
            value *= 0.8
        if word.isupper():
            value = -14.0
    elif w.startswith('seiz'):
        value = -3.3 if w.endswith('ures') else -7.8
        if w.endswith('ure'):
            value = -6.6
        if continued and old == 'se':
            value = -10.0
    elif w.startswith('seism'):
        value = -9.0 if current == 'ism' else -4.9
    elif current == 'of':
        if old.startswith('dismiss'):
            value = -5.2
        elif old.startswith('seiz'):
            value = -7.0
        elif old in {'dispose', 'disposed', 'disposing', 'disposal'}:
            value = -2.0
    elif continued:
        # These are letter combinations at a token boundary, not word lists.
        if p.endswith('e'):
            if re.fullmatch(r'iff(?:er)?', current):
                value = 5.5
            elif re.fullmatch(r'i[bdg]er|inger|iler', current):
                value = 3.5
            elif re.fullmatch(r'itz(?:er)?', current):
                value = 5.5
            elif current in {'it', 'its'}:
                value = 1.8
            elif current == 'ito':
                value = 6.0
            elif current.startswith(('is', 'iz')):
                value = -0.5
        if p == 'se' and current in {'id', 'il', 'ine', 'ign', 'ix'}:
            value = -2.0
        if current.startswith(('is', 'iz')) and p.endswith(('s', 'z')):
            value = -0.5
        if current == 'ism' and p.endswith(('s', 'z', 'ch')):
            value = -2.7
        if w.startswith('theism'):
            value = -2.5
        if p == 'sais':
            value = -8.8
    elif current == 'sais':
        value = -3.0

    if current and len(current) > 1 and set(current) == {'·'}:
        value = -0.67
    if age == 1 and previous == 'Title' and s == ':':
        value = -3.56
    return (doc, s, word, age + 1), value

"""Local spelling rules for b+rounded-vowel fragments and numbers after 3.

Short bo/bu fragments (especially buck and bow) are positive. Splitting a
syllable immediately after Latin b produces a stronger response. The
b+ach/ch/igh fragments instead give a negative response. Most longer words
are quiet.
A separate trigger detects the digit after 3, stronger for dates near a month
name. A middle-dot pair gives a negative value. No other components are read.
"""
import calendar
from functools import lru_cache
import regex as re
from anyascii import anyascii

READS = ()
MONTHS = {s.lower() for s in (*calendar.month_name, *calendar.month_abbr) if s}
MONTHS.add('sept')
AFTER_THREE = (1.0, .73, .27, .17, .22, .12, .02, .04, .12, .02)

@lru_cache(maxsize=32768)
def spelling(token):
    # Transliterate alphabetic scripts, not the readings of ideographs.
    if re.search(r'\p{Han}|\p{Hangul}|\p{Hiragana}|\p{Katakana}', token):
        return ''
    return anyascii(token).lower()

@lru_cache(maxsize=32768)
def syllable(s, split=False):
    if s in ('uck', 'uk'):
        return 7.0 if split else 4.7
    if s in ('ow', 'ows', 'uoy'):
        return 5.0 if split else 4.1
    if s == 'ut':
        return 1.8 if split else .32
    if re.fullmatch(r'u(?:f|s)?|ot(?:s|o)?|uch', s):
        return 4.0 if split else 1.9
    if re.fullmatch(r'oo?k|u[cjvwtz]|o[cvz]|u[sf]s?', s):
        return 4.0 if split else (.08 if s == 'ook' else .8)
    if re.fullmatch(r'ach(?:er)?|ich|igh|ast(?:e|er|ing)|ch|unch', s):
        return -2.3 if split else 0.0
    if not split:
        if re.fullmatch(r'uffer(?:s|ing)?|usy|uzz(?:ing)?', s):
            return 1.3
        if re.fullmatch(r'oots?', s):
            return 1.1
        if re.fullmatch(r'oats?|ug', s):
            return .75
    if s == 'o':
        return 1.0 if split else .7
    if s == 'ou':
        return 1.7 if split else 1.3
    if re.match(r'[ou]', s) and len(s) <= 6:
        return 1.0 if split else .15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old, older, month_window = '', '', 0
    else:
        old, older, month_window = carry[1:]
    token = prefix.token_strings[-1]
    s, previous = spelling(token), spelling(old)
    word = s.lstrip(' ._/-:(')
    value = syllable(word[1:]) if word.startswith('b') else 0.0
    if re.search(r'\p{Cyrillic}', token):
        value *= .65
    if previous.endswith('b') and s and not s[0].isspace():
        value = syllable(s, True)
        # A transliterated b is a weaker clue than a literal Latin b.
        if not old.lower().endswith('b'):
            value *= .35
    if len(token) == 1 and token in '0123456789':
        if old == '3' or (older == '3' and old in '.,'):
            value = AFTER_THREE[int(token)]
            if old in '.,':
                value *= .7
            if month_window and token in '01':
                value *= 1.8
    if token == '··':
        value = -1.72
    is_month = s.strip(' .') in MONTHS or token == '月'
    month_window = 3 if is_month else max(0, month_window-1)
    return (doc, token, old, month_window), float(value)

"""Approximate document openings and chat blank lines with readable syntax rules.

Code/markup punctuation, Python keywords, mixed-case identifiers and line
controls receive larger opening values than ordinary words and digits. The
next delimiter of an opening comment block is also positive. Double newlines
after thinking/tool markers or long padding receive negative values. Other
running text is zero, apart from a small negative blank-line baseline.
Individual words' differing opening responses are intentionally not modeled.
"""
from keyword import iskeyword

READS = ()


def onset(text):
    word = text.strip()
    if text == '<|im_start|>':
        return 2.83
    if text == '\t':
        return 4.25
    if text.isspace() and text.endswith('\n') and text.count('\n') == 1:
        return 4.0 if '\r' in text or '\t' in text else 2.85
    if text == '\n\n':
        return 0.33
    if word.startswith('//'):
        return 6.4 if '\n' in text else 3.1
    if word.startswith('#') and word[1:].isalpha():
        return 4.0  # Preprocessor-directive shape, unlike a lone hash.
    if word.startswith('<') and len(word) > 1:
        return 3.5
    if '(' in word and ')' in word:
        return 4.0
    if '(' in word:
        return 2.8 if not text.startswith(' ') else 0.5
    if '_' in word:
        return 2.7
    if any(c in word for c in '){}'):
        return 1.8
    if word.startswith('.') and len(word) > 1 and word[1].isalpha():
        return 3.2
    if '/' in word or (not word.isalnum() and '"' in word):
        return 1.5
    if word.isdigit():
        return -0.25
    if word.isalpha():
        if any(c.isupper() for c in word[1:]) and not word.isupper():
            return 2.5
        if text.startswith(' '):
            return 0.0
        if iskeyword(word):
            return 2.2
        return 0.35 if len(word) > 1 else -0.1
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    if fresh:
        value = onset(text)
    elif text == '\n\n':
        previous = carry[1]
        if previous in ('<think>', '</think>'):
            value = -0.5
        elif previous == '<tool_response>':
            value = -0.22
        elif previous.isspace() and len(previous) >= 4:
            value = -0.4
        else:
            value = -0.04
    elif carry[2] and carry[1].startswith('//') and text == '//':
        value = 2.85  # The next delimiter of an opening comment block.
    else:
        value = 0.0
    return (doc, text, fresh), value

"""Approximate a negative signal for working something out, checking it, or
explaining it. English clause introducers depend on the preceding verb: ordinary
conditional "if" is not treated like "check if". Chinese words are recognized by
the leading action sense in CC-CEDICT, with weaker evidence from a lone character.
Requests and careful/deep processing strengthen the signal; aspect particles can
continue it. This deliberately leaves lexical details and most small activations
at a near-zero baseline. Only eight preceding tokens are retained, resetting at
each document boundary.
"""

from functools import lru_cache
import re
import regex
import cedict
import wordnet
import opencc

READS = ()


def words(text):
    return frozenset(text.split())


# Leading Chinese action senses and their baseline signal sizes.
CONCEPTS = {
    'investigate': (words(
        'analyze analyse examine investigate study research explore check '
        'test verify inspect review seek find search inquire ask question '
        'browse skim observe'
    ), -0.186),
    'judge': (words(
        'compare assess evaluate appraise distinguish discriminate '
        'differentiate determine judge estimate weigh consider deliberate '
        'ponder choose select decide'
    ), -0.101),
    'compute': (words(
        'calculate compute count reckon sum'
    ), -0.168),
    'understand': (words(
        'learn understand comprehend grasp recognize realise realize '
        'master perceive discover discern'
    ), -0.04),
    'experience': (words(
        'experience sense appreciate taste enjoy'
    ), -0.044),
    'explain': (words(
        'explain describe discuss narrate outline summarize summarise '
        'expound elaborate illustrate demonstrate introduce recount talk '
        'chat converse reveal display show prove confirm clarify specify '
        'embody reflect represent'
    ), -0.144),
    'organize': (words(
        'arrange collate sort classify compile formulate'
    ), -0.059),
    'practice': (words(
        'practice practise rehearse'
    ), -0.135),
}

# Verb class: roots, adjustment for IF, adjustment for WHETHER.
VERBS = {
    'checking': (words(
        'check test verify investigate examine inspect'
    ), -0.36, -0.463),
    'resolving': (words(
        'determine assess evaluate ascertain explore'
    ), -0.182, -0.249),
    'proving': (words(
        'prove show demonstrate establish confirm ensure validate certify'
    ), -0.021, 0),
    'seeing': (words(
        'see'
    ), -0.426, -0.216),
    'inquiry': (words(
        'ask wonder know decide consider tell find understand explain '
        'describe discuss specify'
    ), -0.161, -0.043),
}

@lru_cache(maxsize=50000)
def action_concepts(text):
    heads = set()
    for gloss in cedict.glosses(text):
        gloss = re.sub(r'^(?:\([^)]*\)\s*)+', '', gloss)
        if gloss.startswith('to '):
            gloss = re.sub(
                r'to know (?:from|through) experience', 'to experience', gloss
            )
            gloss = re.sub(r'to (?:take|have) a look', 'to examine', gloss)
            gloss = re.sub(
                r'to look (?:over|into|through|up|around|at)',
                'to examine', gloss
            )
            gloss = re.sub(r'to think (?:over|about)', 'to consider', gloss)
            heads.update(re.findall(r'(?:^|;\s*)to ([a-z]+)', gloss))
            break
    return frozenset(k for k, (verbs, _) in CONCEPTS.items() if heads & verbs)

@lru_cache(maxsize=50000)
def han_concepts(s, previous):
    if not regex.fullmatch(r'\p{Script=Han}+', s): return frozenset()
    # Recognize a whole word, or a word completed by a one-character token.
    if len(s) == 1:
        paired = action_concepts(previous[-1:] + s)
        if paired: return paired | action_concepts(s)
    direct = action_concepts(s)
    if direct: return direct
    if len(s) == 2 and s[0] == s[1]:
        if any(g.startswith('to think') for g in cedict.glosses(s[0])):
            return frozenset({'judge'})
        return action_concepts(s[0])
    if len(s) > 2 and not cedict.glosses(s):
        shorter = s[:-2] if s.endswith('一下') else s
        return action_concepts(shorter[-2:])
    return frozenset()

TO_SIMPLE = opencc.OpenCC('t2s')
INTENT = regex.compile(
    r'(?:请|要求|必须|希望|要|需要|应当|应该|可以|进行|来|开始|'
    r'深入|仔细|认真|详细|深刻|亲身|具体)$'
)



@lru_cache(maxsize=50000)
def verb_class(word):
    bases = set(wordnet.base_forms(word, 'verb')) | {word}
    return next((k for k, (roots, _, _) in VERBS.items() if bases & roots), '')


def clause_value(tail, current):
    words_before = tail.lower().split()
    match = re.search(r'([a-z]+)[^a-z]*$', tail.lower())
    prev = match[1] if match else ''
    kind = verb_class(prev)
    value = 0.0
    if current == 'whether':
        if (prev and prev not in {'and', 'or', 'but'}
                and not tail.rstrip().endswith((',', ';', ':'))):
            value -= 0.212
        if 'question' in words_before[-5:] or 'unclear' in words_before[-4:]:
            value -= 0.319
    if not kind:
        return value
    roots, if_value, whether_value = VERBS[kind]
    if current in {'if', 'whether'}:
        value += if_value if current == 'if' else whether_value
        if kind == 'checking' and re.search(
            r"\b(?:let me|let us|let's|need to|have to|must)\b",
            ' '.join(words_before[-6:])
        ):
            value -= 0.304
    elif current == 'that' and kind in {'checking', 'proving'} and prev in roots:
        value -= 0.226 if kind == 'checking' else 0.028
        if kind == 'proving' and (len(words_before) == 1 or any(
            w in {'we', 'i', 'you', 'to', 'will', 'must', 'please', 'now',
                  "let's", 'us', 'me'} for w in words_before[-4:-1]
        )):
            value -= 0.164
    elif current == 'why':
        value -= 0.341
    elif current in {'how', 'when', 'where', 'what'}:
        value -= 0.056
    return value


def chinese_value(tail, token):
    previous = regex.search(r'\p{Script=Han}+$', tail)
    previous = previous.group() if previous else ''
    concepts = han_concepts(token, previous[-6:])
    paired = action_concepts(previous[-1:] + token)
    strength = 0.25 if len(token) == 1 and not paired else 1.0
    value = strength * sum(CONCEPTS[c][1] for c in concepts)
    if concepts:
        context = tail
        if len(token) == 1 and paired:
            context = tail[:-1]
        elif len(token) > 2 and not cedict.glosses(token):
            context = tail + token[:-2]
        if INTENT.search(TO_SIMPLE.convert(context[-8:])):
            value -= 0.330
    if token in {'了', '过', '過', '着', '著', '一下'} and (
        action_concepts(previous[-2:]) or action_concepts(previous[-1:])
        or action_concepts(previous[-1:] * 2)
    ):
        value -= 0.265
    return value


CLAUSE_WORDS = {'if', 'whether', 'that', 'why', 'how', 'when', 'where', 'what'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = () if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1].strip()
    value = -0.0018
    if token.lower() in CLAUSE_WORDS or regex.search(r'\p{Script=Han}', token):
        tail = b''.join(previous).decode('utf-8', errors='replace')
        value += clause_value(tail, token.lower())
        value += chinese_value(tail, token)
    return (doc, (previous + (raw,))[-8:]), float(value)

"""Approximate a spelling-sensitive f feature, not a topic.

Selected fi stems are positive; ford and fy are negative. Recognize f split
from its continuation, and an s appended to fig. Supplementary figure/file
references are stronger. Greek/Cyrillic text is transliterated for these tests.
Smaller, idiosyncratic token effects are deliberately left unexplained.
