import regex as re
from anyascii import anyascii

READS = ()
FI_STEMS = {'fib', 'fibs', 'fish', 'fishes', 'finger', 'fingers', 'fiction'}


def latin(text):
    if re.search(r'\p{Script=Cyrillic}|\p{Script=Greek}', text):
        return anyascii(text)
    return text


