    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token, previous = latin(raw), latin(tail)
    s = token.lstrip(' \t\r\n-_').lower()
    match = re.search(r'[a-z]+$', previous.lower())
    last_word = match.group() if match else ''
    joined = bool(token[:1].isalpha() and previous[-1:].isalpha())
    split = previous.lower().endswith('f') and token[:1].isalpha()
    word = 'f' + s if split else s
    if joined and s == 's' and last_word == 'fig':
        word, split = 'figs', True

    value = 0.0
    if word in FI_STEMS:
        value = 2.08 + 1.27 * (joined and not split) + 1.90 * split
        value += 0.54 * word.startswith('finger')
    elif word.startswith('fig') and len(word) <= 4:
        value = 1.22 + 1.07 * token.islower() + 0.65 * split
    elif word in ('figure', 'figures'):
        value = 0.49 + 0.58 * word.endswith('s')
    elif word in ('file', 'files'):
        value = 0.06
    elif word.startswith('fi') and not split:
        value = 0.05
    if word == 'ford':
        value = -1.85 - 1.32 * joined
    if word == 'fy' or (split and re.fullmatch(r'i(?:ed|es)', s)):
        value = -2.65 - 0.57 * split
    if split and value == 0.0:
        if re.match(r'i(?:ck|tch)|ach', s):
            value = -1.90
        elif re.match(r'i[bcglr]', s):
            value = 1.22
        elif re.match(r'i[ds]|a[bc]', s):
            value = 1.19
        elif s.startswith('ec'):
            value = 0.82
    if word.startswith(('fig', 'file')) and last_word in (
        'additional', 'supplemental', 'supplementary', 'data'
    ):
        value += 1.98 + 2.34 * (word == 'file')
    return (doc, (tail + raw)[-32:]), float(value)

"""An approximate detector of short written AC/AK/AQ syllables.

It responds negatively to these spellings within a token or across a token
boundary, including transliterated alphabets and kana (but not Han text).
Long chunks, common English words, soft c, and silent-e spellings are weaker.
The response lingers briefly into a following subword. Document starts and
repeated middle-dot separators receive separate positive offsets.
"""
import math
import re
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')

@lru_cache(maxsize=100000)
def spelling(raw):
    # Retain Arabic alif as an a-vowel, which anyascii otherwise omits.
    s = anyascii(re.sub('[اآأ]', 'a', raw)).lower()
    s = re.sub(r'^[^a-z]+|[^a-z]+$', '', s)
    han = bool(HAN.search(raw))
    strength = 0.
    m = re.search(r'a(?:[ckq]|ts)', s)
    if m and s.isalpha() and not han:
        tail = s[m.end():]
        strength = 1.4
        if m.start():
            strength = .35
        elif m[0] == 'aq':
            strength = 1.9
        elif m[0] == 'ak':
            if tail.startswith('e'):
                strength = .35
            elif tail and tail[0] in 'aiou':
                strength = 1.7
        elif tail:
            if tail[0] == 'k':
                strength = .2
            elif tail[0] in 'hcei':
                strength = .55
            elif tail[0] == 't':
                strength = 1.
        strength *= math.exp(-.22 * len(tail) - .45 * m.start())
        if len(s) > 2 and raw.isascii():
            frequency = zipf_frequency(raw.strip(), 'en')
            strength *= max(.12, 1. - .28 * max(0., frequency - 3.))
    if raw == ' AC':
        strength = .3  # A word-boundary acronym, rather than a syllable.
    return s, han, strength

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prior = 0. if first else carry[1]
    raw = prefix.token_strings[-1]
    s, han, strength = spelling(raw)
    old_raw = '' if first else prefix.token_strings[-2]
    old, old_han, _ = spelling(old_raw)
    # Allow one intervening nonalphabetic token, e.g. A, C.
    if not old and not first and prefix.position >= 2 and '\n' not in old_raw:
        if prefix.document_ids[-3] == doc:
            old_raw = prefix.token_strings[-3]
            old, old_han, _ = spelling(old_raw)
    spaced = raw[:1].isspace()
    if old.endswith('a') and s and not (han or old_han):
        consonant = ''
        if s[0] in 'ckq':
            consonant = s[0]
        elif s.startswith('ts'):
            consonant = 'c'
        if consonant:
            cross = 2. if consonant == 'q' else 1.6
            if s.startswith('ch') and not CYRILLIC.search(raw):
                cross = .7
            if old_raw == ' a':
                cross = .95
            if spaced and old_raw.strip() != 'A':
                cross = .15 * (1. if len(s) == 1 else .15)
            strength += cross * math.exp(-.25 * max(0, len(s) - 1))
    value = .0008 + (.306 if first else 0.) - strength
    if not spaced and s.isalpha():
        value -= prior * (.48 if len(s) <= 2 else .13)
    if len(raw) >= 2 and set(raw) == {'·'}:
        value += 2.03
    return (doc, strength), float(value)

