"""Conditional "if" words in Chinese and Japanese (如果, 若, 如有, もし, ...).

layers.1.mlp.down_proj:5583 is a token-identity detector for the word that opens
a conditional clause. It is strongly positive on 如果 and 若 (the usual Chinese
"if" / "if-then"), moderately positive on the rarer conditional forms, and near
zero everywhere else. The program predicts the activation from the current token
alone, so it has no carried state.
"""

READS = ()

# Strong: the standard Chinese conditional words, activation about 6 in the data.
STRONG = {"如果", "若", "如果你", "若你"}
# Weaker: other conditional openers, activation about 3 in the data.
WEAK = {"如有", "如若", "若是", "假如", "假若", "倘若", "要是", "万一", "もし"}
# Partial form, seen once at about 1.
PARTIAL = {"如"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in STRONG:
        value = 6.0
    elif tok in WEAK:
        value = 3.0
    elif tok in PARTIAL:
        value = 1.0
    else:
        value = 0.0
    return carry, value

