"""Written vowel contacts at subword boundaries, not a semantic category.

Short e+a and a+i continuations tend to be positive; e+i and o+ie
continuations tend to be negative. Syllable shape, capitalization, and a
few longer vowel sequences refine this approximation. Most other tokens
receive nearly zero. Document starts have a separate small baseline.
The constants are fitted activation levels, not linguistic probabilities.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    cur = prefix.token_strings[-1]
    word = cur.strip()
    w = word.lower()
    if first:
        return None, -0.14

    prev = prefix.token_strings[-2]
    left = prev[-1:].lower()
    pair = left + cur[:1].lower()
    one_letter = len(prev.strip()) == 1
    silent_e_shape = bool(re.fullmatch(r'[aeiouy][^aeiouy]e', w))

    # A vowel followed by an uppercase OP fragment in an acronym.
    if one_letter and prev[-1:] in 'AEIOUY' and word == 'OP':
        return None, -4.84

    if pair == 'ea':
        if w[1:2] == 'y':
            return None, 6.24
        if w[1:2] == 'e':
            return None, 5.0 if one_letter else 1.64
        # The spelling "yea", including short continuations of it.
        if prev.lower().endswith('ye') and len(w) <= 4:
            return None, 6.5 if w == 'ats' else 2.3
        if one_letter:
            return None, 1.04 if len(w) == 2 else 0.219
        if silent_e_shape and len(prev.strip()) <= 3:
            return None, 0.801
        return None, 0.012

    if pair == 'ei':
        if silent_e_shape:
            return None, -1.18 if w[1:2] == 'n' else -0.097
        if w[1:2] == 'g':
            closed = bool(re.fullmatch(r'i[^aeiouy]{2}', w))
            return None, -1.07 if closed else -0.138
        if prev[-1:] in 'AEIOUY':
            return None, -0.763 if len(w) == 3 else -0.084
        return None, -0.004

    if pair == 'ai':
        if w[-1:] == 'a':
            return None, 4.46 if word.isupper() else 2.0
        if w == 'io':
            return None, 2.48
        if w.startswith('ie') and len(w) <= 3:
            return None, -0.92
        return None, 0.112

    if pair == 'oi' and w.startswith('ie') and len(w) <= 3:
        return None, -3.59
    if pair == 'ya' and w == 'ay':
        return None, 5.55

    # The same short endings may be contained in one capitalized token.
    if re.fullmatch(r'Ya(?:[lt]e?s?|z|y)', word):
        return None, 1.11
    return None, 0.002

"""A coarse document-onset signal, with readable lexical categories.

Predict a large response only while the document consists of repetitions
of its first token. Possessives, small counting words and directional
prepositions tend positive; articles, digits and punctuation are weaker.
The literal test family is negative; name and line families are positive.
Values are rounded estimates based on training category averages, not
exact token responses.
Once a different token supplies context, predict a near-zero background.
"""
import inflect
import wordnet

READS = ()
COUNTING_WORDS = frozenset(
    inflect.engine().number_to_words(i) for i in range(1, 10)
)


def onset_value(text):
    word = text.strip()
    if text.startswith('<|'):
        return 0.19
    if not word:
        return 1.5 if text.count('\n') >= 2 else -0.45
    if word.isdecimal():
        return -3.2 if word == '0' else -0.45
    if not any(c.isalnum() for c in word):
        if '\n' in text:
            return 1.5
        if word in {',', ';', '，', '；', '、'}:
            return -0.96
        if word in {'(', '[', '{'}:
            return -2.23
        if word[0] in '\'"`“‘':
            return 2.34
        if word.startswith('#') or word.startswith('//'):
            return -1.23
        return 0.2
    # Recognize inflected words even after a path or identifier separator.
    lexeme = word.lstrip('/_.(').lower()
    if lexeme.isascii() and lexeme.isalpha():
        roots = wordnet.base_forms(lexeme)
        if 'test' in roots:
            return -11.5 if lexeme == 'test' else -3.0
        if 'name' in roots:
            return 10.0
        if 'line' in roots:
            return 12.0
    if not word.isalpha():
        return 1.1
    lower = word.lower()
    if lower in {'my', 'mine'}:
        return 17.4
    if lower in {'our', 'ours', 'your', 'yours', 'his', 'her', 'hers',
                 'its', 'their', 'theirs'}:
        return 6.0
    if lower == 'the':
        return -0.3
    if lower == 'a':
        return -0.4 if word.isupper() else 1.8
    if lower == 'an':
        return 6.1
    if lower in COUNTING_WORDS:
        return 7.4
    if lower in {'that', 'those'}:
        return -3.65
    if lower in {'no', 'not', 'never', 'neither', 'none', 'if', 'unless',
                 'whether', 'although', 'though', 'while'}:
        return -1.6
    if lower in {'to', 'from', 'into', 'onto', 'toward', 'towards',
                 'through', 'across', 'along', 'past'}:
        return 4.9
    if word.isascii() and 'verb.motion' in wordnet.categories(lower):
        return 3.6
    return 2.0 if word.islower() else 1.3


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, token, onset_value(prefix.token_strings[-1]))
    elif carry[1] != token:
        carry = (document, None, 0.002)
    return carry, carry[2]

"""A negative detector for short si/ci/zi-like spelling fragments.

Use ASCII transliteration, with a few script-specific adjustments.
Splitting the consonant and front vowel across tokens strengthens the response;
short -il/-yl fragments are especially strong. Long endings and familiar
word prefixes are weaker. A short following fragment can retain some of the response.
Ordinary Han characters are mostly excluded; Katakana shi and short
Cyrillic/Arabic front-vowel syllables have separate strengths. This is a
spelling heuristic, not a pronunciation model.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
FRONT = re.compile(r'(?:sh|zh|ts|ch|[sczx])[eiy]')
ENDING = re.compile(r'[sczx][iy]$')
COMMON_ENDINGS = ('ing', 'ion', 'ity', 'ical', 'ive', 'ible', 'ist',
                  'ize', 'ise', 'ish', 'ition', 'itation', 'idence',
                  'ian', 'in', 'is', 'it', 'id', 'ics')
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'pl', 'tr', 'ru')

@lru_cache(maxsize=20000)
def letters(text):
    return anyascii(text).lower()

@lru_cache(maxsize=20000)
def familiarity(word):
    return max(zipf_frequency(word, language) for language in LANGUAGES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, previous, before_previous, word = carry
    raw = prefix.token_strings[-1]
    s = letters(raw)
    joined = bool(s and previous and raw[0].isalpha()
                  and previous[-1].isalpha())
    word = ((word if joined else '') + s)[-50:]
    word = word.split()[-1] if word.split() else ''
    boundary = previous[-3:] + s
    split = joined and any(m.start() < len(previous[-3:]) < m.end()
                           for m in FRONT.finditer(boundary))
    match = FRONT.search(s)
    value = 0.0
    if split:
        if s.startswith('e'):
            value = -0.06
        elif s in ('il', 'yl'):
            value = -4.1 if s == 'yl' else (-2.5 if previous.endswith('s') else -1.3)
        elif s in ('i', 'y', 'ig', 'yg', 'iv', 'yv', 'ie', 'ye'):
            hard_cluster = previous.endswith(('cc', 'sc', 'ts', 'sh', 'ch'))
            value = -0.23 if hard_cluster else (-1.75 if len(word) <= 3 else -1.15)
        elif len(s.strip()) <= 3:
            if s.startswith(COMMON_ENDINGS):
                value = -0.25
            elif previous.endswith(('cc', 'sc', 'ts', 'sh', 'ch')):
                value = -0.16
            elif previous.endswith('c'):
                value = -1.4 if familiarity(word) < 3.8 else -0.5
            else:
                value = -1.55 if s.startswith(('il', 'yl')) else -0.68
        else:
            value = -0.92 if s.startswith(('il', 'yl')) else -0.01
    elif ENDING.search(s) and len(s.strip()) <= 3:
        if not raw.isascii():
            value = -0.22
        elif familiarity(word) < 3.6:
            value = -1.35 if len(s.strip()) <= 2 else -0.61
            if s.strip().startswith('x'):
                value = -0.48
        else:
            value = -0.37
    elif match:
        value = -0.08 if len(s.strip()) <= 3 else -0.01
    if value > -0.1 and joined and len(s.strip()) <= 3:
        # Carry over only onto a tiny continuation, not an ordinary ending.
        ended_front = (ENDING.search(previous)
                       and len(previous.strip()) <= 3
                       and len(s.strip()) == 1)
        split_vowel = (previous.strip() in ('i', 'y')
                       and before_previous.endswith(('s', 'c', 'z', 'x')))
        if ended_front or split_vowel:
            value = -0.83
    # Romanization alone overgeneralizes to ordinary Chinese characters.
    if regex.search(r'\p{Script=Han}', raw):
        value = -0.2 if s == 'xi' else 0.0
    elif regex.fullmatch(r'[シー]+', raw):
        value = -1.6
    elif regex.search(r'\p{Script=Cyrillic}', raw) and s in ('si', 'tsi'):
        value = -0.85
    elif regex.search(r'\p{Script=Arabic}', raw) and re.fullmatch(r'[sz][iy].?', s):
        value = -1.0
    return (doc, s, previous, word), value

