Selected incomplete UTF-8 fragments, especially partial Han characters,
receive negative values. Short Thai consonant and leading-vowel fragments
also receive negatives. Vietnamese syllable onsets get larger negatives,
reduced for capitals. Grammatical words establish Vietnamese context;
subsequent accented Latin letters maintain it. Other positions get zero.
This does not model the remaining token-specific variation.
"""
import codecs
import unicodedata

READS = ()
VIETNAMESE_ONSETS = frozenset('''
    b c ch d đ g gh gi h k kh l m n ng ngh nh p ph q qu
    r s t th tr v x
'''.split())

VIETNAMESE_FUNCTION_WORDS = frozenset(
    'và của một những các không được với trong'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', 1000, '')
    _, pending, previous, age, unfinished_word = carry
    fragment = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(fragment, 'ignore', False)
