                value = -1.1
            elif len(word) == 2 and consonants:
                value = -0.5
            elif len(word) == 2 and word[0] in 'เแโใไ':
                value = -0.6
            elif len(word) == 1 and word in 'เแโใไ':
                value = -0.9

    return (doc, pending, text[-1:] or previous, age, unfinished_word), value

