be forms, apostrophe-s, and space-prefixed German present be forms fire.
Most token-specific variation remains unexplained.
"""
READS = ()
GERMAN_PRESENT_BE = frozenset('bin bist ist sind seid'.split())

ARTICLES = frozenset('a an the'.split())
PRONOUNS = frozenset('i me you he him she her it we us they them'.split())
DEMONSTRATIVES = frozenset('this that these those'.split())
# Responses of the ten decimal digits when they open a document.
DIGITS = (-.832, -.012, -.307, -.068, .337,
          .375, .372, .395, .434, .285)


def opening_value(s):
    w = s.strip()
    if len(s) == 1 and s in '0123456789':
        return DIGITS[int(s)]
    if s == '<|im_start|>':
        return .331
    if s == '<|endoftext|>':
        return -.706
    if '\t' in s:
        return -1.51 if s == '\t' else -.75
    if '\n' in s:
        return -.30
    if s.isspace():
        return .119 if s == ' ' else -.36
    if w and all(c in ',;' for c in w):
        return -.24
    if w and all(c in '.!?' for c in w):
        return .125
    if w and all(c in '"“”' for c in w):
        return .18
    if w and all(c in '([{' for c in w):
        return .01
    if w and all(c in ')]}' for c in w):
        return .20
    if w.startswith('#'):
        return -.28
    value = -.167 + .018 * s.isascii()
    value += .139 * (w.isascii() and w.isalpha())
    value += .128 * w.istitle() - .217 * w.isupper()
    value -= .181 * min(len(s), 16) / 16
    value += .151 * (w.lower() in ARTICLES)
    value += .218 * (w.lower() in PRONOUNS)
    value += .289 * (w.lower() in DEMONSTRATIVES)
    return value


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(s)
        return (doc, 0, prefix.token_bytes[-1], s, True, value), value
    _, pos, first, previous, opening_run, first_value = carry
    pos += 1
    opening_run = opening_run and prefix.token_bytes[-1] == first
    state = (doc, pos, first, s, opening_run, first_value)
    if opening_run:
        return state, first_value
    if first == b'1' and s == '2':
        if pos == 1:
            return state, -2.0
        if pos == 2 and previous == '2':
            return state, -.845
    # Shortened English present-tense copulas versus German finite forms.
    normalized = s.strip().replace('’', "'")
    if normalized in ("'m", "'re"):
        return state, .16
    if normalized == "'s":
        return state, .025
    if s.startswith(' ') and normalized in GERMAN_PRESENT_BE:
        return state, -.19
    return state, 0.0

