"""layers.1.mlp.down_proj:5589 -- a weak, mostly token-specific component.

What it does, in plain terms:
- It is almost silent. Its activation is near 0 at nearly every token (std 0.04), and it
  essentially never passes the causal-importance threshold, so the model barely uses it.
- The large values come from the first token of each document (when a packed row starts a
  new document, the model resets attention, so that token sees only itself). There the
  activation is about -0.3 for whitespace, +0.09 on average for a capitalised word with no
  leading space (a sentence opener), and about -0.1 for digits.
- Elsewhere the sign follows the word. Contraction forms "'m", "'re" and the unspaced word
  "are" are positive. "will" (unspaced) and copulas or modals of other languages, such as
  " ist", " sind", " är", " è", " est", " sont", " wird", are negative. Spaced "did", "does",
  "would", "has", "should" are weakly positive.

This program predicts those group means and 0 for everything else. It explains only a
small part of the variance: the rest is spread over thousands of mid-frequency tokens with
no shared concept.
"""

READS = ()

# English contraction forms, written without a leading space: positive.
BE_CONTRACTIONS = {"'m", "’m", "'re", "’re"}
# The word "are" without a leading space: positive.
UNSPACED_ARE = {"are"}
# Auxiliaries written with a leading space: weakly positive.
AUX_SPACED = {" did", " does", " would", " has", " should"}
# "will", and copulas or modals of other languages: negative.
FUTURE_AND_FOREIGN_BE = {
    "will", " Will", " Wil", " ist", " sind", " är", " è", " est", " zijn", " sont",
    " waren", " wird", " kan", " kann",
}


def start_value(s):
    """Activation of a document's first token, by its kind."""
    if s.strip() == "":
        return -0.26
    c = s.lstrip()[:1]
    if c.isdigit():
        return -0.10
    if s[:1] != " " and c.isupper():
        return 0.09
    return -0.04


def step(carry, prefix, upstream):
    """Predict this position's activation from its token and whether it opens a document."""
    s = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        return carry, start_value(s)
    if s in BE_CONTRACTIONS:
        return carry, 0.16
    if s in UNSPACED_ARE:
        return carry, 0.11
    if s in AUX_SPACED:
        return carry, 0.04
    if s in FUTURE_AND_FOREIGN_BE:
        return carry, -0.18
    return carry, 0.0

programs.sol:
"""Approximate local vowel-fragment effects, leaving other tokens at zero.

Arabic alef/waw/ya fragments after a word-initial consonant are negative,
including consonants following an Arabic definite article. Cyrillic vowel
hiatuses and isolated Japanese/Korean vowel syllables are positive. This uses orthography and the previous token, not word meaning;
it omits lexical exceptions and incomplete UTF-8 characters.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    previous = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    prior = previous.strip()
    first = word[:1]
    before = prior[-1:]

    if word == 'ウ':
        name = unicodedata.name(prior[:1], '') if prior else ''
        return None, 2.14 if 'KATAKANA' in name else 0.71
    if word == 'い':
        return None, 0.67 if len(prior) > 1 else 0.14
    if word == '우':
        return None, 1.05 if text.startswith(' ') else 1.24
    if not word or text[:1].isspace():
        return None, 0.0

    # Remove a definite article, possibly preceded by a one-letter clitic.
    onset = prior
    for article in ('وال', 'بال', 'كال', 'فال', 'لل', 'ال'):
        if onset.startswith(article):
            onset = onset[len(article):]
            break
    # A split just after the root's initial consonant.
    if (previous.startswith(' ') and len(onset) == 1 and
            'ARABIC' in unicodedata.name(onset, '') and
            onset not in 'ايوىأإآ'):
        if first == 'ا':
            if len(word) == 2:
                return None, -2.0
            if len(word) <= 3:
                return None, -0.65
        if first in ('و', 'ي') and len(word) <= 3:
            return None, -0.7

    # Cyrillic vowels on both sides of the token boundary.
    if before == 'е':
        return None, {'и': 1.71, 'у': 2.12, 'о': 0.60,
                      'е': 0.28}.get(first, 0.0)
    if before == 'о':
        return None, {'и': 0.42, 'у': 1.73, 'о': 0.31,
                      'е': 0.16}.get(first, 0.0)
    return None, 0.0

programs.haiku:
"""Candidate v3: a mid-word Arabic-script fragment (a token with no leading space) that
begins with alef (ا) is pushed negative, about -0.5; other mid-word Arabic fragments get
a tiny negative. Everything else, including all Latin text, is 0.

Constants are the mean activations of these groups on 3,072 training rows."""

READS = ()

ALEF = "ا"
ALEF_VALUE = -0.5
OTHER_ARABIC_VALUE = -0.05


def is_arabic(s):
    return any(0x0600 <= ord(c) <= 0x06FF or 0xFB50 <= ord(c) <= 0xFEFF for c in s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    v = 0.0
    if is_arabic(s) and not s.startswith(" "):
        v = ALEF_VALUE if s[:1] == ALEF else OTHER_ARABIC_VALUE
    return carry, float(v)

programs.sol:
"""Respond to counted years, more than to calendar-year references.

The strength grows from small counts to decades and is stronger in hyphenated
age/duration adjectives. East Asian four-digit calendar years have the
opposite sign. English calendar references are weaker or negative; other
time units have small fixed responses. Unusual subword spellings are omitted.
The state is just a short text tail, reset at document boundaries.
"""
import re
import inflect

READS = ()
_inflect = inflect.engine()
NUMBERS = {
    _inflect.number_to_words(n).replace('-', ' '): n for n in range(1, 100)
}
NUMBERS.update(hundred=100, thousand=1000, million=1000000, billion=1000000000)
ORDINALS = {
    _inflect.number_to_words(_inflect.ordinal(n)).replace('-', ' '): n
    for n in range(1, 100)
}
CALENDAR = set('''this that the last next current fiscal academic school new
same past coming upcoming calendar previous following'''.split())
DURATIONS = set('''several many few couple dozen long short full whole half
quarter some multiple numerous'''.split())
FOREIGN_YEARS = {
    'jaar', 'jaren', 'jahr', 'jahre', 'jahren', 'año', 'años', 'ans',
    'anni', 'anos', 'лет', 'год', 'года', 'году',
}
EAST_ASIAN_YEARS = {'年', '年前', '年間', '年の', '年に', '년'}


def count(history):
    digits = re.search(r'(\d+(?:\.\d+)?)\s*[-–—]?$', history)
    if digits:
        return float(digits[1]), False
    digits = re.search(r'(\d+)(st|nd|rd|th)\s*[-–—]?$', history)
    if digits:
        return float(digits[1]), True
    words = re.findall('[a-z]+', history.lower())
    for size in (2, 1):
        phrase = ' '.join(words[-size:])
        if phrase in NUMBERS:
            return NUMBERS[phrase], False
        if phrase in ORDINALS:
            return ORDINALS[phrase], True
    return None, False


def counted_strength(n):
    if n < 2:
        return 1.3
    if n < 5:
        return 2.1
    if n < 10:
        return 3.5
    if n < 20:
        return 4.8
    return 5.3 if n < 100 else 3.0


def response(token, history):
    raw = token.strip()
    word = raw.strip('-–—').lower()
    relevant = (word in {'year', 'years', 'yr', 'yrs', '年度', '年代', '日',
                         '周年', 'anniversary', 'anniversaries', 'hour', 'hours',
                         'hr', 'hrs', 'century', 'centuries'} or
                word in FOREIGN_YEARS or word in EAST_ASIAN_YEARS)
    if not relevant:
        return 0.0
    n, ordinal = count(history)
    words = re.findall(r'\w+', history.lower())
    last = words[-1] if words else ''
    if word in EAST_ASIAN_YEARS:
        return -4.6 if n is not None and n >= 1000 else 3.5 if n else 0.1
    if word == '年度':
        return -1.0
    if word == '年代':
        return -1.5
    if word == '日':
        return -1.2 if n is not None else 0.0
    if word in {'周年', 'anniversary', 'anniversaries'}:
        return 2.2
    if word in {'hour', 'hours', 'hr', 'hrs'}:
        return 0.35
    if word in {'century', 'centuries'}:
        return -0.45
    if word in FOREIGN_YEARS:
        if raw.isupper() or not token.startswith(' '):
            return 0.0
        if n is not None:
            return -0.3 if n >= 1000 else counted_strength(n) + 1.2
        return 1.8 if word in {'jahr', 'jahre', 'jahren', 'jaar', 'jaren'} else 0.3
    if word in {'yr', 'yrs'}:
        return 2.6
    hyphen = raw.startswith(('-', '–', '—')) or history.endswith('-')
    if token[:1].isalpha() and history[-1:].isalnum():
        return 1.1  # Year inside an identifier, not a separate counted unit.
    if n is not None:
        value = counted_strength(n) + 1.2 * ordinal
        if hyphen:
            value += 2.0 + 1.7 * (n >= 10)
        if re.search(r'\b(age|aged|younger|older|adults?)\b', history[-70:], re.I):
            value += 0.9
    elif word == 'years':
        value = 1.1 if last in DURATIONS else 0.25 if last in CALENDAR else 0.7
    else:
        value = 0.8 if last in {'each', 'every'} else 0.0 if last in CALENDAR else 0.85
    if word == 'year':
        value += {'this': -1.0, 'next': -0.7, 'last': -0.4,
                  'that': -0.2, 'the': -0.2}.get(last, 0.0)
    return value + 0.5 * raw[:1].isupper()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = response(token, history)
    return (document, (history + token)[-100:]), value

"""A mostly lexical detector for 'one', especially the Chinese glyph 一.

The isolated glyph is strongest in Chinese prose, weaker in Japanese, and
negative as a parenthesized list number. Fused grammatical phrases are weaker.
A few completed quantity phrases suppress the response. Short horizontal lines
also respond in East Asian prose, but not in ordinary English hyphenation.
The small glossary below covers a few other written forms of one. Pairs of
middle dots get a negative response only in an all-dot document prefix.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
HAN_NUMERALS = frozenset('〇零二三四五六七八九十百千万萬亿億廿卅')
# 'This one', 'only', and 'single', versus 'first', 'same', and 'one of'.
SPECIFIC_ONE = {'这一', '這一', '唯一', '单一', '單一'}
WEAK_ONE_COMPOUNDS = {'第一', '同一', '之一'}
OTHER_ONE_FORMS = {
    'single': 0.25,
    '1': 0.017,
    'một': 0.4,       # Vietnamese one
    '하나': -2.1,     # Korean one
}


def response(text, recent, only_dots):
    word = text.strip()
    if word == '一':
        before = recent.rstrip()
        if before.endswith(('(', '（')):
            return -0.7
        if not before:
            return 0.8
        if recent.endswith('\n'):
            return 1.8
        if before[-1] in HAN_NUMERALS:
            return 1.6
        return 2.8 if KANA.search(recent) else 4.2
    if word in SPECIFIC_ONE:
        return 4.5
    if word in WEAK_ONE_COMPOUNDS:
        return -0.1
    if word.endswith('一'):
        return 1.0
    if word.endswith(('一个', '一個')):
        return 0.55
    if word in {'壹', '壱'}:
        return 2.3
    # Half, one person, and one repetition are negative completions.
    if word in {'一半', '另一半'}:
        return -2.5
    if word == '半' and recent.endswith('一'):
        return -3.8
    if word == '一个人':
        return -1.35
    if word == '一遍':
        return -2.2
    if word in OTHER_ONE_FORMS:
        return OTHER_ONE_FORMS[word]
    # Persian 'yek' (one), including a final letter in a separate token.
    if word in {'یک', 'يك'} or (
        word in {'ک', 'ك'} and recent.endswith(('ی', 'ي'))
    ):
        return 1.2
    if word and all(c in '-—–─ー' for c in word):
        japanese = bool(KANA.search(recent))
        chinese = bool(HAN.search(recent)) and not japanese
        if '-' in word:
            return 0.35 if chinese else 0.0
        return 1.0 if chinese else 0.35 if japanese else 0.0
    if word == '··':
        return -1.0 if only_dots else 0.05
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, only_dots = '', True
    else:
        _, recent, only_dots = carry
    text = prefix.token_strings[-1]
    value = response(text, recent, only_dots)
    only_dots = only_dots and bool(text) and all(c == '·' for c in text)
    return (doc, (recent + text)[-48:], only_dots), value

"""Approximate negative responses at joins between short phonetic pieces.

Use Unicode scripts and dictionary transliteration, not token IDs.  The
largest responses covered here follow an open a-syllable, especially before
Korean liquid/j/m sounds or Japanese ta/to/chi/ra sounds. A few rules
cover Han syllable joins, ai/ay after g, and repeated middle dots; most other
contexts stay at zero. Month-counter joins and the Japanese ma-de limit
marker get separate negative responses, as does the spelling "int" at an
attention reset. These are surface rules, not a claim about the model's internals.
"""
from functools import lru_cache
import re
import regex
from anyascii import anyascii

READS = ()

MONTH_COUNTERS = ('か', 'カ', 'ヵ', 'ヶ', 'ケ', '个', '個', '箇')

# These are consonant onsets, rather than lists of vocabulary tokens.
KOREAN_A = {'l': -0.6, 'j': -0.6, 'm': -0.5, 'd': -0.65}
# Romaji spellings unite the same syllables in hiragana and katakana.
JAPANESE_A = {
    'ta': -1.0,
    'to': -0.6,
    'chi': -1.2,
    'ra': -1.0,
    'ru': 0.15,
    'yu': -1.4,
    'wa': -0.5,
    'na': -0.5,
    'ne': -0.5,
}

@lru_cache(maxsize=65536)
def describe(text):
    word = text.strip()
    roman = anyascii(word).lower()
    script = ''
    for name in ('Hangul', 'Hiragana', 'Katakana', 'Han', 'Latin'):
        if regex.search(r'\p{Script=' + name + '}', word):
            script = name
            break
    vowel = re.search(r'[aeiou]+$', roman)
    onset = re.match(r'[bcdfghjklmnpqrstvwxyz]+', roman)
    return (script, roman, vowel[0] if vowel else '',
            onset[0] if onset else '', len(word), text[:1].isspace())

def response(previous, current):
    script, roman, vowel, onset, length, spaced = current
    pr, pv = previous[1:3]
    if spaced:
        return 0.0
    if script == 'Hangul' and length == 1:
        if pv == 'a':
            if onset == 'j' and vowel == 'i':
                return -5.5 if pr.endswith('ga') else -1.0
            if pr.endswith('ga') and roman.startswith('seu') and not vowel:
                return -2.5
            if onset == 's' and vowel == 'eo':
                return 2.0 if pr.endswith('ga') else -0.1
            if onset == 'm' and vowel == 'u':
                return -2.5
            if onset == 'l' and vowel in ('a', 'i', 'u'):
                return -2.0
            return KOREAN_A.get(onset, -0.2)
        if onset == 'l':
            if pv in ('o', 'u') and vowel in ('i', 'ae'):
                return -1.6 if pv == 'o' else -0.8
            return -0.25 if pv == 'o' else -0.12
    if script in ('Hiragana', 'Katakana') and length == 1:
        if pv == 'a':
            return JAPANESE_A.get(roman, -0.1)
        if roman == 'ra' and pv in ('i', 'u'):
            return -0.65
        if onset == 'r':
            return -0.1
        if pv == 'o' and onset == 't':
            return -0.3
    if script == 'Han' and length == 1 and pv == 'ia':
        return -0.9 if onset in ('j', 'l') else -0.2
    if (script == 'Latin' and roman in ('ai', 'ay')
            and pr.endswith('g')
            and not pr.endswith('ng')):
        return -0.8
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    current = describe(text)
    value = -3.086 if text == 'int' else 0.0
    if carry is not None and carry[0] == doc:
        value = response(carry[1], current)
        word, previous = text.strip(), carry[3]
        if not current[5]:
            if ((word == '月' and previous.endswith(MONTH_COUNTERS))
                    or (word == '월' and previous.endswith('개'))):
                value = -3.0
            elif previous.endswith('ま') and word.startswith('で'):
                value = -2.0
        if len(text) >= 2 and not text.strip('·') and carry[2]:
            value = -2.26
    dots = len(text) >= 2 and not text.strip('·')
    return (doc, current, dots, text.strip()), value

"""A sparse guan/quan/kan-like spelling detector, not a general semantic test.

Large negative responses mark relation/view characters in Chinese/Japanese,
Korean 관, and `an` completing Latin `qu` or `gu`. Related compounds and a
few neighboring characters get smaller responses. Recent Vietnamese tone
marks enable a response to `qu` itself. Some split UTF-8 encodings have their
own strengths. Independently, the colon of a document-opening `Title:` fires.
Weak background activity is omitted; these rules approximate the main peaks.
"""
from functools import lru_cache
import opencc
import unicodedata

READS = ()
_SIMPLIFY = opencc.OpenCC('t2s')

@lru_cache(maxsize=4096)
def character_response(text):
    if text.strip() in ('係', '覚'):
        return -2.0
    text = _SIMPLIFY.convert(text.strip()).replace('関', '关')
    if text == '关':
        return -8.5
    if text in ('观', '観'):
        return -5.0
    if text == '관':
        return -6.5
    if text == '管':
        return -0.9
    if text in ('官', '感'):
        return -0.55
    # Care, attention, affection and tariff words are weak exceptions.
    if '关' in text and text not in ('关心', '关注', '关税', '关爱'):
        # Crucial / passing a gate; concerning / unrelated.
        if text in ('至关', '过关'):
            return -7.0
        if text in ('事关', '无关', 'に关'):
            return -4.0
        return -2.4 if len(text) == 2 else -1.0
    if text.endswith('观'):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new = carry is None or carry[0] != doc
    position = 0 if new else carry[1] + 1
    previous = '' if new else carry[2]
    tail = b'' if new else carry[3]
    vietnamese_age = 0 if new else max(0, carry[4] - 1)
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    joined = tail + raw
    value = character_response(text)
    # Horns, breves, underdots and hook-above tones identify Vietnamese text.
    decomposed = unicodedata.normalize('NFD', text.lower())
    viet_marks = ('đ', '\u0306', '\u031b', '\u0323', '\u0309')
    if any(ch in decomposed for ch in viet_marks):
        vietnamese_age = 24
    if vietnamese_age and text.strip().lower() == 'qu':
        value = -2.6
    if text == '关' and previous.endswith('网'):
        value = 0.1  # 网关 is the lexicalized technical term 'gateway'.
    if text == 'an' and previous.strip().lower() in ('qu', 'gu'):
        value = -9.0
    # 観 and 関 sometimes arrive as two or three separate UTF-8 fragments.
    if raw == b'\xe8\xa6':
        value = -1.6
    if raw == b'\xb3' and joined.endswith('観'.encode()):
        value = -8.0
    if raw == b'\x96' and joined.endswith(b'\xe9\x96'):
        value = -7.2
    if raw == b'\xa2' and joined.endswith('関'.encode()):
        value = -16.5
    if position == 1 and previous == 'Title' and text == ':':
        value = -12.67
    return (doc, position, text, joined[-3:], vietnamese_age), value

"""Approximate a negative type/membership-relation signal.

Recognize annotation colons, return-type arrows, inheritance, and mathematical
membership. Stronger pulses mark explicit declarations; ordinary punctuation
stays near zero. A document-initial Title label has a positive pulse.
Use a small first-token baseline and a short, document-local text buffer.
"""
import re

READS = ()
LATEX = {'in': -1.69, 'notin': -.21, 'rightarrow': -1.42,
         'longrightarrow': -1.22, 'to': -1.76, 'times': -.82,
         'subset': -3.21, 'subseteq': -1.61}
RELATIONS = {'extends': (-1.45, -2.51), 'implements': (-1., -1.97),
             'instanceof': (-1.16, 0.), 'throws': (-.41, 0.)}
TYPES = {'bool', 'str', 'int', 'float', 'string', 'void', 'Optional',
         'Union', 'Option', 'Result', 'list', 'tuple', 'interface'}


def signal(token, before):
    s = token.strip()
    if s in RELATIONS:
        base, declaration = RELATIONS[s]
        if re.search(r'\b(class|interface)\b', before[-150:]):
            base += declaration
        if s == 'throws' and before.rstrip().endswith(')'):
            base -= 3.09
        return base
    if s == '∈':
        return -1.74
    if s in LATEX and before.endswith('\\'):
        return LATEX[s]
    if s == '{' and re.search(r'@(param|type|returns?)\s*$', before):
        return -1.33
    if s in {'*', "*'", '&', "&'"}:
        if re.search(r'\b(func|fn)\b', before[-180:]):
            return -2.19 if s.startswith('&') else -.75
    if s in TYPES and re.search(r'[:>]\s*$', before):
        return -.35
    if s == 'of' and re.search(r'\bfor\s*\([^;)]*$', before[-140:]):
        return -1.65
    # A colon and its type can occupy the same token (for example ':Int').
    if re.fullmatch(r':\w+', s) and before and before[-1].isalnum():
        s = ':'
    if s not in {':', '?:', '():', '):', '::', '->'}:
        return 0.
    if s == ':' and before == 'Title':
        return 6.21
    if s == '::':
        return -1.04 if token.startswith(' ') else 0.
    tail = before[-550:]
    line = tail.rsplit('\n', 1)[-1].rsplit('\\n', 1)[-1]
    line = re.sub(r'^\s*\d+\t', '', line)
    heads = list(re.finditer(r'\b(def|fn|func|function)\b', tail))
    head = tail[heads[-1].start():] if heads else ''
    clean_head = bool(head) and not any(c in head for c in '{};')
    if s == '->':
        if not token.startswith(' '):  # C++/PHP member access, not a type arrow.
            return .09
        return (.06 - 1.39 * before.rstrip().endswith(')')
                - 5.72 * clean_head)
    if '\n' in token or '\\n' in token:
        return -.02
    control = re.match(r'\s*(if|elif|else|while|try|except|finally|with|case|match)\b', line)
    if control or (re.match(r'\s*for\b', line) and
                   (line.rstrip().endswith(')') or '(' not in line)):
        return -.04
    if s == '?:':
        return -3.46
    if s in {'():', '):'}:
        php = heads and heads[-1].group(1) == 'function'
        scala = re.search(r'\b(final|override)\s+def\b', line)
        if php or scala:
            return -4.60
        if heads and heads[-1].group(1) == 'def':
            return -.12
        method = re.fullmatch(
            r'\s*(public |private |protected |static |async )*\w+', line)
        if re.search(r':\s*\w+', line) or method:
            return -.67
        return -.17
    stripped = before.rstrip()
    if stripped.endswith(('"', "'")) or re.search(r'(?<!\w)\d+\s*$', before):
        return -.02
    if re.search(r'\b(class|interface)\s+\w+[^{};=()]*$', line):
        modified = re.search(
            r'\b(public|private|protected|final)\s+'
            r'(?:(abstract|sealed|partial|static)\s+)*(class|interface)\b', line)
        return -6.4 if modified else -2.69
    if re.search(r'\b(let|const|var|val)\s+(mut\s+)?[\w$]+\s*$', line):
        return -8.27
    if re.search(r'\b(private|public|protected|readonly)\s+(static\s+)?[\w$]+\s*$', line):
        return -4.39
    signature = clean_head and head.count('(') > head.count(')')
    arrow_function = re.search(r'\b(const|let)\s+\w+\s*=\s*\([^{};)]*$', tail)
