        return -3.67 if re.search(r'(?<!:):(?!:)', declaration) else -7.37
    if re.search(r'\b(interface|struct|type)\s+\w+[^{}]*\{[^{}]*$', tail):
        return -4.19
    method = re.match(
        r'\s*(public |private |protected |async |static )*\w+\([^;={}]*$', line)
    if method and not re.search(r'\b(new|return)\b', line):
        if re.search(r'\b(public|private|protected|static)\b', line):
            return -5.0
        typed = re.search(
            r':\s*([A-Z]\w*|string|number|boolean|int|str|float)\b', line)
        return -2.41 if typed else -.37
