            r'\b(theorem|lemma|axiom)\b|⊢|-- (goal|after)|[ℝℕℤℚ]', tail)
        return -2.82 if proof else -1.90
    if stripped.endswith(')') and not re.search(r'\bdef\b', line):
        return -1.19
    return -.52 if token.startswith(' ') else -.06


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, start = '', True
    else:
        _, before, start = carry
    value = .23 if start else signal(token, before)
    if token == '<|endoftext|>':
        before, start = '', True
    else:
        before, start = (before + token)[-600:], False
    return (doc, before, start), float(value)

"""A pulse on short letter-runs split across tokens.

Three capital letters give a small positive value; four give a negative
value, strongest for unfamiliar, vowel-less initialisms. Five give a weaker
negative value. Lowercase runs only get a strong pulse if all four letters
are consonants. Familiar English word beginnings reduce the capital pulse.
Only ASCII letters count; punctuation and document boundaries reset the run.
"""
import re
from wordfreq import top_n_list, zipf_frequency

READS = ()
VOWELS = frozenset('aeiou')

# Familiarity of four- and five-letter beginnings in an English word list.
WORD_BEGINNINGS = {}
for word in top_n_list('en', 50000):
    if word.isascii() and word.isalpha():
        frequency = zipf_frequency(word, 'en')
        for length in (4, 5):
            if len(word) >= length:
                beginning = word[:length]
                WORD_BEGINNINGS[beginning] = max(
                    frequency, WORD_BEGINNINGS.get(beginning, 0.0)
                )


def pulse(word, piece):
    n = len(word)
    no_vowels = not any(ch in VOWELS for ch in word.lower())
    consonant_start = piece[0].lower() not in VOWELS
    if word.isupper():
        if n == 3:
            return 0.12 if consonant_start else 0.02
        familiarity = WORD_BEGINNINGS.get(word.lower(), 0.0)
        if n == 4:
            if familiarity == 0:
                return -2.0 if no_vowels else -1.0
            return -0.46 if familiarity <= 4.0 else -0.06
        if n == 5:
            if familiarity == 0:
                return -0.70 if consonant_start else -0.23
            return -0.06
    elif word.islower() and n == 4:
        return -0.83 if no_vowels else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    head = re.match(r'[A-Za-z]+', token)
    value = 0.0
    if before and head:
        piece = head.group()
        value = pulse(before + piece, piece)
    tail = re.search(r'[A-Za-z]+$', token)
    after = ''
    if tail:
        after = before + token if tail.group() == token else tail.group()
    # Longer runs cannot trigger a short-run pulse, so bounded state suffices.
    return (doc, after[-20:]), value

programs.haiku:
"""Comment-continuation detector for layers.1.mlp.down_proj:5600 (Qwen3-1.7B, layer 1).

In plain terms: the component is silent almost everywhere and fires on the comment
marker that opens a new line of a comment, when the line above was also a comment
(`//`, `///`, `#`, `*`, `>` at the start of a line, after indentation):

  - strongest (1.2) when the comment line above is long (50+ characters), i.e. a full
    hard-wrapped comment line, so the comment obviously continues on this line;
  - 0.8 when the comment block is already two or more lines deep but the line above
    is short;
  - 0.35 when the line above is a short first comment line.

Two weaker cases:
  - a comment marker that opens a trailing comment after code on the same line
    ("x = 1  // note"): 0.3 if the marker has a leading space, 0.1 otherwise
    (a bare `>` is ignored, since it is usually HTML or quoted text);
  - indentation that opens a new line after a long (70+ characters) plain-prose line,
    the look of hard-wrapped prose or documentation: 0.1.

Everything else is 0. The values were chosen by fitting training text: they sit near the
average activation in each case. The program looks only at the current and previous lines.

Carry: the current line so far, the last non-blank line and how many comment lines in a
row end there. The state resets at each document boundary, as the model's attention does.
"""

READS = ()

MARKERS = ("//", "///", "#", "*", ">")
COMMENT_LEADS = ("/", "#", "*", ">")
LONG_LINE = 50  # characters
LONG_PROSE = 70


def is_comment_line(line):
    """A line that starts (after indentation) with a comment marker."""
    return line.lstrip(" \t")[:1] in COMMENT_LEADS


def step(carry, prefix, upstream):
    if carry is None or prefix.document_ids[-1] != carry["doc"]:
        carry = {"doc": prefix.document_ids[-1], "line": "", "prev": "", "run": 0}
    tok = prefix.token_strings[-1]
    bare = tok.lstrip(" \t")
    value = 0.0
    if bare in MARKERS and "\n" not in tok:
        if carry["line"].strip() == "":
            # opens a line: a comment line continuing a comment line above it
            if carry["run"] >= 1:
                if len(carry["prev"]) >= LONG_LINE:
                    value = 1.2
                elif carry["run"] >= 2:
                    value = 0.8
                else:
                    value = 0.35
        elif bare != ">":
            # a trailing comment after code on the same line
            value = 0.3 if tok.startswith(" ") else 0.1
    elif bare == "" and tok != "" and carry["line"] == "":
        # indentation opening a new line after a long line of plain prose
        if len(carry["prev"]) >= LONG_PROSE and not is_comment_line(carry["prev"]):
            value = 0.1
    prev, run, line = carry["prev"], carry["run"], carry["line"]
    pieces = tok.split("\n")
    for i, piece in enumerate(pieces):
        if i > 0:  # a newline ends the line so far
            if line.strip():
                prev = line
                run = run + 1 if is_comment_line(line) else 0
            line = ""
        line += piece
    carry = {"doc": carry["doc"], "line": line, "prev": prev, "run": run}
    return carry, float(value)

