    'job': -0.6, 'books': -1.1, 'latest': -0.4, 'researchers': -1.8,
    'sense': -0.9, 'nearest': -1.0, 'spot': -2.2,
    'importance': -0.9, 'scenes': -0.2, 'century': -1.2,
    'peace': -2.4, 'square': -0.7, 'race': -0.8, 'better': -0.7,
    'way': -0.2, 'difference': -0.6, 'country': 0.5, 'case': 0.1,
