        value = (2.8 if capital else 1.4) if s.endswith('s') else (
            2.7 if capital else 1.7)
    elif stem == 'centre':
        value = 2.5 if s.endswith('s') else 3.5
    elif stem == 'centro':
        value = 7.5 if capital else 4.8
    elif s in {'centered', 'centred'}:
        value = 1.6
    elif s in {'theatre', 'theater'} and prev != 'the':
        value = 0.55
    elif s == 'concert':
        value = 1.3
    elif s == '中心':
        value = 0.7
    elif s == 'центр':
        value = 4.0
    elif continuing and before and word.startswith(before):
        # Completing a stem across a token boundary is often much stronger.
        if before.endswith('цент') and s.startswith('р'):
            value = 7.0
        elif before in {'ц', 'конц'} and s.startswith('ент'):
            value = 3.8
        elif before.endswith('теат') and s.startswith('р'):
            value = 3.8
        elif before.endswith('ithe') and s in {'atre', 'ater', 'aters'}:
            value = 8.2
        elif before.endswith(('theat', 'teat')) and s in {'re', 'ro'}:
            value = 3.9
        elif before.endswith('the') and s in {'atre', 'ater', 'atres'}:
            value = 3.5
        elif before.endswith('cent') and s in CENTR_ENDINGS:
            value = 5.8
        elif before.endswith('zent') and s in {'rum', 'ri', 'rier'}:
            value = 7.5 if s == 'rum' else 3.4
        elif before.endswith('c') and s in {'enter', 'entre'}:
            value = 4.2
        elif before.endswith('cent') and s in {'er', 'ers'}:
            value = 3.8
        elif before.endswith(('con', 'kon', 'ren')) and s in {
            'tr', 'tro', 'tros', 'tra', 'tre'
        }:
            value = 3.8
        elif before.endswith('count') and s == 'erc':
            value = 5.4
        elif before == 'tr' and s == 'ung':
            value = 4.6
        elif before.endswith('center') and s == 'ing':
            value = 2.8

    # English collocations; the governing word distinguishes their senses.
    if prev == 'the':
        value = DEFINITE.get(s, value)
        if s == 'age' and prev2 == 'at':
            value = -3.45
        elif s == 'age' and prev2 in {'under', 'over', 'by'}:
            value = -2.6
        elif s == 'sense' and prev2 == 'in':
            value = -3.4
        elif s == 'spot' and prev2 == 'on':
            value = -5.8
        elif s == 'nearest' and prev2 == 'to':
            value = -3.6
        elif s == 'scenes' and prev2 == 'behind':
            value = -2.6
        elif s == 'case' and prev2 == 'in':
            value = 0.75
        elif s == 'country':
            value = 1.0 if prev2 in {'in', 'into'} else (
                -0.1 if prev2 == 'across' else 0.65)
        elif s == 'difference' and prev2 in {'make', 'makes', 'all'}:
            value = -3.8
        elif text in {'Year', 'Great'}:
            value = -0.8
    elif s == 'country':
        value = -0.2
    if s == 'for' and prev in {'center', 'centre'} and previous.strip()[:1].isupper():
        value = 5.3
    elif s == 'of':
