        elif prev == 'age' and last_value < -2:
            value = -0.8
        elif previous.strip() == 'Order':
            value = -0.75
    elif s == 'between':
        if prev in {'difference', 'differences', 'gap'}:
            value = -0.85
        elif prev in {'choice', 'choose', 'choosing', 'deciding'}:
            value = -2.6
    elif s == 'where':
        if prev in {'point', 'stage'}:
            value = -1.1
        elif prev == 'to':
            value = -0.4

    # A header delimiter and sustained dot leaders, not arbitrary punctuation.
    if s == ':' and previous == 'Title' and older in {'<|endoftext|>', ''}:
        value = 4.98
    dots = dots + 1 if s and not s.strip('·') else 0
    if dots >= 3:
        value = -1.08
    return (doc, token, previous, word, value, dots), value

"""Approximate a lexical feature centered on the written syllable 'yu'.

The strongest cues are 与/與 ('and/with') and 雨 ('rain'), all Mandarin yǔ.
宇 ('space') and 羽 ('feather') are weaker yǔ cues. Other Mandarin yu
characters and compounds get small responses. Latin 'yu', including a
'u' token continuing 'y', is another cue. Most other text predicts zero.

Two separate document-opening responses handle 'Title:' and initial '12'.
State resets at document boundaries; split UTF-8 characters are reassembled.
This deliberately omits the many weak, arbitrary token-specific responses.
"""
import codecs
from functools import lru_cache
import regex
from pypinyin import lazy_pinyin, Style

READS = ()


@lru_cache(maxsize=16384)
def lexical(text):
    text = text.strip()
    if text in ('与', '與', '雨'):
        return 4.55
    if text in ('宇', '羽'):
        return 2.9
    if '与' in text or '與' in text:
        return 1.65
    if text.lower() == 'yu':
        return 1.6
    if any(c in text for c in '于於'):
        return 0.75 if len(text) == 1 else 0.28
    if not regex.fullmatch(r'\p{Script=Han}+', text):
        return 0.0
    readings = lazy_pinyin(text, style=Style.TONE3)
    if len(text) == 1:
        strengths = {'yu3': 0.7, 'yu2': 0.55, 'yu4': 0.18}
        return strengths.get(readings[0], 0.0)
    if any(r.startswith('yu') and r[2:].isdigit() for r in readings):
        return 0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, tail, previous = 0, b'', ''
    else:
        _, position, tail, previous = carry
    raw = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    if raw and 0x80 <= raw[0] < 0xC0:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        decoder.decode(tail)
        text = decoder.decode(raw)
    value = lexical(text)
    if text.lower() == 'u' and previous.lower().endswith('y'):
        value = 2.5
    if position == 1 and previous == 'Title' and text == ':':
        value = -2.96
    elif position == 1 and previous == '1' and text == '2':
        value = 2.25
    return (doc, position + 1, (tail + raw)[-3:], text), value

"""Document-opening signal, with smaller code-expression boundary signals.

The opening token is classified by script, commonness, numbers and spacing.
A prefix repeating only that token keeps its opening signal.
Later, plain assignments, block openings and return/break/continue get a
small positive value. Everything else is approximately inactive.
These broad rules omit vocabulary-specific fluctuations.
"""
import re
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def opening(s):
    word = s.strip()
    if not word:
        if '\n' in s:
            return -2.7
        if '\t' in s and len(s) > 1:
            return 1.2
        return -2.1 if len(s) == 1 else -0.9
    if word == '<|endoftext|>':
        return -7.7
    if word == '<|im_end|>':
        return 6.2
    if word == '<|im_start|>':
        return 9.8
    if word[0].isdigit():
        if word[0] == '0':
            return -2.9
        if word[0].isascii():
            return 0.8 + 0.18 * int(word[0])
        return 2.0
    if word[0] == '\ufffd':
        return 5.6
    if not word[0].isalpha():
        return 1.0
    if regex.match(r'\p{Script=Han}', word):
        return 5.8
    if not regex.match(r'\p{Script=Latin}', word):
        return 7.0
    frequency = zipf_frequency(word.lower(), 'en')
    return (7.8 - 0.24 * min(len(word), 12) + 0.20 * frequency
            - 1.11 * max(frequency - 5.0, 0.0)
            + 1.05 * word[0].isupper() - 0.39 * (len(word) == 1))


def boundary(s, previous):
    text = previous.replace('\\n', '\n').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1]
    token = s.strip()
    if token in {'return', 'break', 'continue'}:
        if not line.strip() or re.match(r'^[\d |\t]*$', line):
            return 1.1
        if re.search(r'[);{}]', line):
            return 0.7
    if token in {'=', ':=', '<-', '=>'}:
        if token == '=' and '\n' in s:
            return 0.0
        if token == '=>':
            return 0.7
        if token == '<-':
            return 2.1
        if token == ':=':
            return 1.0
        if re.search(r'\b(const|var|let)\b', line):
            return 1.1
        if re.match(r'^\s*[\w.\[\](),]+\s*$', line):
            return 0.8
        return 0.3
