        left = line + s.split('{', 1)[0]
        if re.search(r'\)\s*$|\b(else|try|finally|do)\s*$', left):
            return 1.0
        if not line.strip() and re.search(r'\)\s*$', text.rstrip()):
            return 0.9
    if ':' in s and ('\n' in s or '\\' in s or 'case' in line):
        if re.search(
            r'(^|\s)(if|elif|else|for|while|def|class|try|except|finally|with|case)\b',
            line,
        ):
            return 1.0
    if token == '<' and not line.strip():
        return 0.9
