        'return', 'break', 'continue', '<-', '<', 'php'
    }:
        value = boundary(s, previous)
    else:
        value = 0.0
    return (doc, (previous + s)[-300:], opening_token, repeated), float(value)

"""Approximate a response to unaccented Latin fragments in Vietnamese text.

Recent Vietnamese-specific letters supply a language cue. Plain syllables and
unfinished consonant onsets receive negative values. Frequent longer syllables
receive less. Continuations of words containing non-ASCII letters are exempt.
A few document-initial quotation/spacing effects are modeled separately.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

ONSET = r'(?:ngh|ng|nh|gh|ch|kh|ph|th|tr|gi|qu|[bcdghklmnpqrstvx])'
SYLLABLE = re.compile(ONSET + r'?[aeiouy]+(?:ng|nh|ch|[cmnpt])?$')
CONSONANTS = re.compile(ONSET + r'$')
TRAILING_LETTERS = re.compile(r'[^\W\d_]+$')


@lru_cache(maxsize=16384)
def fragment(s):
    word = s.strip()
    if not (word.isascii() and word.isalpha() and len(word) <= 8):
        return None
    w = word.lower()
    return (w, bool(CONSONANTS.fullmatch(w)),
            bool(SYLLABLE.fullmatch(w)), zipf_frequency(w, 'vi'),
            word.istitle())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
