        elif syllable:
            amplitude = max(0.0, 4.0 - 6.0 * max(0.0, frequency - 5.8))
            if continuation:
                amplitude *= 0.6
            if len(w) == 1:
                amplitude = 1.8
        else:
            amplitude = 0.0
        value = -confidence * amplitude
