"""Approximate a sparse punctuation and boilerplate response.

On each line, count ellipses, exclamations, mixed stops, and terminators
after short function words. When these indicate repeated broken snippets,
predict large positive sentence-punctuation values, especially after
articles and prepositions. This is a surface-text heuristic, not a parser.

Smaller rules cover source-code phrase endings, repeated middle dots,
certain document openings, and weak punctuation baselines. Unmatched
tokens default to zero. All state resets at document boundaries.
"""
READS = ()
UNFINISHED = set("a an the of to and or".split())

# These words usually require something after them, rather than a full stop.
NEEDS_COMPLEMENT = set(
    "a an the of to for with and or at by in on from into through "
    "between under over as than".split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, bangs, ellipses, mixed, broken, tail = "", 0, 0, 0, 0, ""
    else:
        _, previous, bangs, ellipses, mixed, broken, tail = carry
    s = prefix.token_strings[-1]

    is_bang = s in ("!", ".!", ",!")
    is_ellipsis = s in ("..", "...", "....", ",...")
    is_mixed = s in (".!", ",!", ",.", ".,")
    bangs += is_bang
    ellipses += is_ellipsis
    mixed += is_mixed

    terminal = s in (
        ".", "!", "..", "...", "....", ".!", ",!", ",.", ",..."
    )
    broken += terminal and previous.strip().lower() in UNFINISHED
    # Require unfinished phrases or mixed stops, not just enthusiastic prose.
    run_on = ellipses >= 1 and bangs >= 1 and (broken >= 2 or mixed >= 1)
    incomplete = previous.strip().lower() in NEEDS_COMPLEMENT
    value = 0.0
    if s == ".":
        value = (8.2 if incomplete else 4.2) if run_on else 0.01
    elif s == "!":
