            1.8 if previous.strip().lower() in UNFINISHED else 0.0
        )
    elif s in ("..", "...", "...."):
        value = (11.6 if incomplete else 9.8) if run_on else 0.17
    elif s in (".!", ",!"):
        value = 18.0 if run_on else 4.0
    elif s in (",.", ",..."):
        value = 12.8 if run_on else 0.3
    elif s == "··" and previous == "··":
        value = 0.94

    # Stock source-code header and import completions.
    if s == ".annotation" and tail.endswith(".springframework.web.bind"):
        value = -4.1
    elif s == ".annotation" and tail.endswith(".springframework.context"):
        value = -2.5
    elif s == ".stereotype" and previous == ".springframework":
        value = -2.25
    elif s == ".Tasks" and tail.endswith("System.Threading"):
        value = -3.1
    elif s == " charset" and tail.endswith("text/html;"):
        value = -10.5
    elif s == " Templates" and tail.endswith("Tools |"):
        value = -6.8
    elif s == " License" and tail.endswith("limitations under the"):
        value = -3.5
    elif s == " SOFTWARE" and "OTHER DEALINGS" in tail[-100:]:
        value = -6.0
    elif s == "_RESULTS" and tail.endswith("@OLD_CHARACTER_SET"):
        value = -7.0

    if first:
        if s in ("def", "public"):
            value = 1.9
        elif s in ("package", "using", "import"):
            value = -0.95
        elif s == "//\n":
            value = 4.73
        elif s in ("\\n", "\\t"):
            value = 2.4
        elif s.isspace() and " " in s and "\n" in s:
            value = 1.04
        elif s.isspace() and "\u00a0" in s:
            value = 1.84
        elif s == "•":
            value = 2.0
        elif s == "<|im_start|>":
            value = -0.2
        elif s == "<|endoftext|>":
            value = 1.83

    if "\n" in s:
        bangs = ellipses = mixed = broken = 0
    return (doc, s, bangs, ellipses, mixed, broken, (tail + s)[-256:]), value

"""Approximate a naming signal and a secondary c/k spelling effect.

Definitions ('called', 'known as') are negative; ordinary calls and aliases
are weaker. Noun heads help distinguish definitions from actions. Call/cast
chunks split across tokens are especially negative, while short cake/candy/
cub/cup-like chunks are positive. A document-initial 'Title:' and repeated
middle dots have separate fixed responses. Other guesses are shrunk by 0.8;
unmatched tokens predict zero.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
CALL = re.compile(r'(?:re)?call(?:ed|ing|s|er|ers|able|e)?$', re.I)
SPLIT_CALL = re.compile(r'[ck]all(?:ed|ing|er|s|able)?$', re.I)
SPLIT_CAST = re.compile(r'cast(?:er|s)?$', re.I)
SPLIT_L = re.compile(r'[ck][ao]l(?:le|let|led|lo|lee)$', re.I)
SPLIT_OTHER = re.compile(r'c(?:ull|oll|ut(?:ter)?|ard|arr)$', re.I)
POSITIVE = re.compile(
    r'[ck](?:ak(?:e|es|ing)?|ach(?:ed|ing|ers)?|and(?:y|s)?|'
    r'ub(?:e[sd]?|s)?|uc|up(?:s)?|ock(?:s)?)$', re.I)
DEFINITION_HEADS = {
    'process', 'processes', 'phenomenon', 'technique', 'mechanism',
    'principle', 'condition',
}
PERSONAL = {'i', 'you', 'he', 'she', 'we', 'they', 'them'}
OTHER_AUX = {'was', 'were', 'be', 'being', 'been', 'have', 'has', 'had'}
NOUN_CUES = {'a', 'an', 'the', 'this', 'that', 'some', 'of'}


@lru_cache(maxsize=4096)
def noun_strength(word, noun_cue):
    if wordnet.is_a(word, 'person') or 'noun.time' in wordnet.categories(word):
        return -1.8
    classes = wordnet.parts_of_speech(word)
    if 'noun' in classes and ('verb' not in classes or noun_cue):
        return -4.7
    return -3.0


def predict_text(s, prev, before):
    w, p, b = (x.strip().lower() for x in (s, prev, before))
    if w == 'as':
        if p == 'known':
            if b in OTHER_AUX | {'better', 'best', 'well', 'now', 'became'}:
                return -3.0
            if b == 'also' or b.endswith('ly') or b in {'often', 'sometimes'}:
                return -3.8
            if b in DEFINITION_HEADS:
                return -8.5
            return -7.5 if b in {'is', 'are'} else -6.5
        if p == 'know':
            return -2.6
        return -3.4 if p == 'to' and w == s.strip() else 0.0
    value = 0.0
    if CALL.fullmatch(w.strip('._-')):
        if w.startswith('recall'):
            value = -2.1
        elif w.endswith('called'):
            if p == 'so' or w.startswith('-'):
                value = -0.8
            elif p in OTHER_AUX or p in PERSONAL:
                value = -1.1
            elif p == 'is':
                if b in DEFINITION_HEADS:
                    value = -8.5
                elif b in {'this', 'what'}:
                    value = -7.0
                else:
                    value = -1.5 if b in {'method', 'function'} else -3.8
            elif p == 'are':
                value = -5.4
            elif p in {',', '('}:
                value = -5.8
            elif p == 'something':
                value = -8.0
            elif p in {'also', 'often', 'sometimes', 'commonly', "'s", '’s'}:
                value = -3.9
            elif prev == ' ' + p and p in DEFINITION_HEADS:
                value = -9.5
            elif any(ch.isupper() for ch in prev):
                value = -1.3
            else:
                value = noun_strength(p, b in NOUN_CUES)
        elif w.endswith('calls'):
            value = -0.6
        elif w.endswith('calling'):
            value = -1.0
        else:
            value = -1.3
            if w == 'call' and p == 'we':
                value = -4.5 if b == 'what' else -2.5
        if s[0].isalpha() and p.endswith('re') and w == 'call':
            value = -5.5
    elif w in {'cast', 'casting', 'casts', 'cut', 'carr', 'kill'}:
        value = -1.0
    elif len(w) <= 5 and POSITIVE.fullmatch(w):
        value = 1.5 if w.startswith(('cak', 'cand')) or w == 'cub' else 0.8
        if w == 'cup':
            value = 1.0 if s.strip()[0].isupper() else 0.3
            if p == 'world':
                value = 2.5
    # A word can continue across a token boundary. First matching family wins.
    if s and s[0].isalpha():
        left = re.search(r'[A-Za-z]+$', prev)
        if left:
            a = left.group()
            for pattern, strength in (
                (SPLIT_CALL, -5.5), (SPLIT_CAST, -4.8),
                (SPLIT_L, -3.6), (SPLIT_OTHER, -1.7), (POSITIVE, 1.6),
            ):
                for m in pattern.finditer(a + s):
                    if m.start() < len(a) < m.end():
                        return strength
    return value


def step(carry, prefix, upstream):
    same = (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2])
    age = carry + 1 if same and carry is not None else 0
    prev = prefix.token_strings[-2] if age else ''
    before = prefix.token_strings[-3] if age > 1 else ''
    s = prefix.token_strings[-1]
    if s == ':' and prev == 'Title' and age == 1:
        return age, -13.5
    if len(s) > 1 and set(s) == {'·'}:
        return age, -1.1
    return age, 0.8 * predict_text(s, prev, before)

programs.haiku:
"""Layer 1 MLP down-projection, component 5610: a "called / call" detector.

What it does, in plain terms:
- Strongly negative on the word that introduces the name of a thing or term:
  "called" and "as" in "known as" / "referred to as". The strongest cases are
  "is called", "are called", "also called", "'s called" and "as" after "known"
  (e.g. "a process called", "known as").
- Moderately negative on "called" used after a noun (e.g. "a band called").
- Weakly negative on "called" as a plain verb or passive ("they called",
  "was called"), and on other forms of call: call, calls, calling, recall, caller.
- Weakly positive on a few concrete nouns that start with "c" (cake, candy, cub,
  cup, cock, cum, cube, corn, cow).
- Slightly negative on the first token of a row, where the model has no context yet.
- Near zero everywhere else.

The program reads only the current token and the one before it (plus the row's
start and document boundaries), so it needs no state between positions.
"""

READS = ()

NAMING_BEFORE = {",", "is", "are", "also", "'s"}
WEAK_BEFORE = {"he", "she", "they", "we", "i", "it", "you", "who", "was", "were", "be", "been", "being", "so", "and"}
CALL_WORDS = {"call", "calls", "calling", "recall", "recalls", "recalled", "recalling", "calle", "caller", "callers"}
C_NOUNS = {"cake", "cakes", "candy", "cub", "cubes", "cube", "cup", "cupcake", "cock", "cum", "corn", "cow", "cob", "cucumber"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    if len(prefix) == 1:
        return None, -0.2
    same_doc = prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if cur == "as":
        if prev == "known":
            return None, -5.0
        if prev == "to":
            return None, -3.5
        return None, 0.0
    if cur == "called":
        if prev in NAMING_BEFORE:
            return None, -4.0
        if prev in WEAK_BEFORE:
            return None, -0.9
        return None, -2.8
    if cur in CALL_WORDS:
        return None, -2.3 if prev in {"we", "i"} else -1.2
    if cur in C_NOUNS:
        return None, 1.2
    return None, 0.0

programs.sol:
"""Approximate a detector of conspicuous code indentation.

Ordinary indentation fades after the first few literal line breaks. Indentation
in escaped code or after line numbers, comment leaders, and diff markers stays
positive. Mixed tabs/spaces and nonbreaking padding near backticks also respond.
There are narrow rules for import statements and line-initial 'if'. State resets
at document boundaries. These are formatting rules, not token-id lookups.
"""
import math
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '')
    _, breaks, line = carry
    s = prefix.token_strings[-1]
    prev = ''
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == doc:
        prev = prefix.token_strings[-2]
    numbered = bool(re.fullmatch(r' *\d+ *(?:[:|])?[ \t]*', line))
    marker = line.strip()
    horizontal = bool(s) and not s.strip(' \t\xa0')
    value = 0.0

    if horizontal:
        width = len(s)
        tabs = s.count('\t')
        if '\xa0' in s:
            if not s.strip('\xa0') and width >= 2:
                value = 1.15 if '`' in line else 0.35
            else:
                value = 0.07
        elif prev.endswith('\n'):
            gain = 0.65 if prev.rstrip().endswith(('{', ':')) else 2.0
            value = gain / max(1, breaks) ** 1.7 - 0.08
            if tabs and ' ' in s:
                value += 0.4
        elif tabs and ((numbered and '\t' not in line) or ' ' in s or
                       (not line.strip() and ' ' in line)):
            value = 1.35 + 0.045 * min(width, 28)
            value += 0.65 * (tabs >= 2)
        elif tabs and numbered and '\t' in line:
            value = 0.3
        elif numbered and ('\t' in line or ':' in line or '|' in line):
            value = 0.7 + 0.28 * math.log2(width + 1)
        elif marker in {'//', '#', '|', '+', '-'}:
            base = 0.65 if marker in {'+', '-'} else 0.3
            value = base + 0.25 * math.log2(width + 1)
        elif not line.strip() and '\t' in line:
            value = 1.1 if not tabs else 0.3
        elif line.endswith('\\n'):
            value = 0.6 + 0.3 * math.log2(min(width, 7) + 1)
            if prev.endswith('\\n'):
                value *= 0.7 if width < 15 else 0.4
        elif tabs and not prev:
            value = 1.95
    elif s == 'import' and prev.rstrip().endswith(';'):
        value = 1.9
    elif prev and s.strip(' \t') == 'if' and (
            prev.isspace() or not line.strip() or line.endswith('\\t')):
        value = 0.65
    elif s.startswith('\t') and s.strip() in {'import', 'from'}:
        value = 1.05
    elif s.startswith('\t') and numbered and '\n' not in s:
        value = 0.65
    elif s == '``' and '\xa0' in prev:
        value = 1.0

    breaks += int('\n' in s)
    line = (line + s)[-150:]
    if '\n' in s:
        line = s.rsplit('\n', 1)[-1]
    return (doc, breaks, line), value

