"""Candidate v6: v5 plus the colon after a test or build status word ('PASS:', 'FAIL:')."""
READS = ()

BACKREF = {" before", " yet", " already", " previously", " recently", " earlier", " above"}
NEG_CONTEXT = {" never", " not", " as", " ever", " been", " done", " have", " has", " had",
               " did", " haven", " hasn", "'ve", "'s", "'t", "t", " seen", " read", " said"}
PREP_CONTEXT = {" on", " or", " just", " of", " in", " for", " at", " the", " years", " year",
                " days", " day", " weeks", " week", " months", " hours", " minutes", " time"}
TAG_START = {" @", "{@", "(@"}
STATUS = {" PASS", " FAIL", " FAILED", " passed", " failed", " SUCCESS", " Testing"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in BACKREF:
        if prev in NEG_CONTEXT or prev.endswith("ed") or prev.endswith("en"):
            return None, -2.5
        if prev in PREP_CONTEXT:
            return None, -0.3
        return None, -0.6
    if prev in TAG_START and tok.isalpha() and not tok.startswith(" "):
        return None, 1.0
    if tok == ":" and prev in STATUS:
        return None, 1.0
    return None, 0.0

programs.sol:
"""A lexical retention-versus-tour feature, including split spellings.

Keeping/retaining words give negative values (retain is strongest); tour
spellings give positive values. Some of the same response occurs in small
syllables split after a t: t+ay/ain is negative, t+w/ou is positive.
Two Chinese keeping words are included too. Other positions get zero.
Only these local spellings are modeled, not the meaning of the whole text.
"""
import re
from anyascii import anyascii

READS = ()


def response(token, previous, word):
    s = token.strip(' _').lower()
    if re.fullmatch(r'retain(?:s|ed|ing|er|ers)?', s):
        return -6.7 if s.endswith('ed') else -7.5
    if s == 'retention':
        return -5.7
    if re.fullmatch(r'keep(?:s|ing|er|ers)?|kept', s):
        return -2.6 if s == 'keep' else -2.1
    if re.fullmatch(r'maintain(?:s|ing)?', s):
        return -1.7
    if s == 'maintained':
        return -1.1
    if re.fullmatch(r'entertain(?:s|ed|ing|er|ers)?', s):
        return -2.0
    if re.fullmatch(r'(?:re)?tours?', s):
        return 3.8 if token.strip().istitle() else 3.3
    if s == 'touring':
        return 1.0
    if s == '保留':
        return -2.5
    if s == '保持':
        return -0.65

    # Recognize word spellings completed across token boundaries.
    joined = word + token.lower()
    if token and token[0].isalpha():
        if re.search(r'retain(?:s|ed|ing|er|ers)?$', joined):
            return -9.0
        if joined.endswith('retention'):
            return -8.0
        if joined.endswith('detention') and s == 'ention':
            return -6.0
        if re.search(r'keep(?:s|ing|er|ers)?$|kept$', joined):
            return -4.8
        if s in ('ers', 'er') and re.search(r'(maintain|entertain)$', word):
            return -3.2

    # Transliteration lets the same short sound/spelling rules cross scripts.
    p = anyascii(previous).lower()
    q = anyascii(token).lower()
    if token and token[0].isalpha() and p.endswith('t'):
        if q == 'our':
            return 4.5
        if q in ('w', 'ow'):
            return 3.0
        if q in ('ou', 'ua', 'uan'):
            return 2.5
        if q in ('u', 'ur', 'ut'):
            return 1.0
        if q in ('ay', 'ai'):
            return -2.8
        if re.fullmatch(r'ain(?:s|e|ed|ing|er|ers)?', q):
            if p.strip(' -_') in ('st', 'cert', 'att', 'cont'):
                return 0.0
            return -4.2 if token.isupper() else -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word = '', ''
    else:
        _, previous, word = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, word)
    # Keep only the current alphabetic word for split-root recognition.
    match = re.search(r'[^\W\d_]+$', word + token.lower())
    word = match.group()[-40:] if match else ''
    return (doc, token, word), value

programs.haiku:
"""Layer-1 MLP component 5613: a word detector for "keep / retain / maintain" (negative)
and "tour" (positive).

The component's activation is large and negative on the word being completed when it is
a form of retain (retain, retained, retention, retains), keep (keep, kept, keeping, keeps),
maintain, or a close relative such as detain or entertain. It is large and positive on the
word "tour" and its compounds (detour, retour). Everywhere else it is near zero.

The program reads the word that ends at the current token (the letters of the decoded text
so far, lowercased), so a word split over several tokens is scored on its last token.
"""

import re

READS = ()

KEEP_WORDS = {"keep", "keeps", "keeping", "kept", "keeper"}
DETAIN_WORDS = {"detain", "detained", "detention", "entertain", "entertained", "entertaining", "pertain"}
TOUR_WORDS = {"tour", "tours", "detour", "retour", "entour"}

LAST_WORD = re.compile(r"[^\W\d_]+$")


def step(carry, prefix, upstream):
    match = LAST_WORD.search(prefix.text_prefixes[-1])
    word = match.group(0).lower() if match else ""
    if "retain" in word or "retent" in word:
        value = -7.0  # retain, retained, retaining, retention: strongest
    elif word in KEEP_WORDS:
        value = -2.2
    elif "maintain" in word:
        value = -1.8
    elif word in DETAIN_WORDS:
        value = -2.5
    elif word in TOUR_WORDS:
        value = 3.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A surface-syntax approximation, not a general mathematical-text detector.

The main positive pattern is a run of empty parentheses, followed by more
parentheses, isolated digits or spaces. Other small rules distinguish empty
and reversed parentheses, coordinate variables, and '0 otherwise'. Document
starts have a negative baseline, with separate code-header/control rules.
Only the last sixteen tokens and a document-initial repetition flag are kept.
"""
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    new = carry is None or carry[0] != doc
    history = () if new else carry[1]
    initial_run = new or (carry[2] and s == history[-1])
    z = s.strip()
    previous = history[-1].strip() if history else ''
    nonspace = [q.strip() for q in history[-4:] if q.strip()]
    pairs = sum(a.strip() == '(' and b.strip() == ')'
                for a, b in zip(history, history[1:]))
    cluster = min(pairs, 4)
    value = 0.0015

    if new:
        if z.isdigit():
            value = -0.075
        elif not z:
            value = -0.057
        elif len(z) == 1 and z.isascii() and z.islower():
            value = -0.13
        else:
            value = -0.18 if s[:1].isspace() else -0.22

    if z == ')' and previous == '(':
        value += 0.14
    if z == '(' and previous == ')':
        value -= 0.07
    if (z == '(' and len(nonspace) > 1 and nonspace[-1].isdigit()
            and nonspace[-2] == ')'):
        value += 0.17
    if z in {'(', ')', '()', '((', ')('}:
        value += 0.33 * cluster
    if z.isdigit():
        value += 0.19 * cluster
    if not z:
        value += 0.04 * cluster
    if z in {'x', 'y', 'z', 't'} and previous in {'x', 'y', 'z', 't'}:
        value += 0.05
    if len(z) > 1 and all(c in '()[]{}' for c in z):
        value -= 0.03
    if z == 'otherwise':
        value = 0.95 if nonspace and nonspace[-1] == '0' else -0.17
    if s.startswith('//'):
        value -= 0.046

    # These are document-opening syntactic forms, not a word lookup table.
    if new and s == '//\n':
        value = -6.62
    elif history == ('//\n',) and s == '//':
        value = -0.72
    elif new and z == '/*':
        value = -1.04
    elif new and z == 'def':
        value = 1.1
    elif history == ('<',) and s == 'filename':
        value = 1.49
    elif initial_run and s == '\r':
        value = -3.24
    elif initial_run and len(z) >= 2 and set(z) == {'·'}:
        value = -0.397

    return (doc, (history + (s,))[-16:], initial_run), float(value)

programs.haiku:
"""Type names that open a declaration (negative).

Component 5616 of layer 1's MLP down-projection goes negative on the word that
names a type when code declares something: `private String name;`, `int i = 0;`,
`List<Game> games`, `public void run()`, `char *p`. It responds to the type, not
the variable: the declared name comes next, and the type's own brackets and
`[]` stay negative too. A type word after `new`, `=`, `return` or `.` is a use,
not a declaration, so it stays near zero, and so does prose.

The strength depends on what comes before the type:
  after `final`, `private`, `const`, `{` or `;`       -4.0  (field or local declaration)
  at the start of a line, after `public`, `}`         -2.2
  inside a parameter list (after `(` or `,`)          -1.6
  any other listed type word                          -0.3
  continuation of an open type (`<`, `>`, `[]`, `*`)  -0.4
  a capitalised word not on the list, starting a line of code   -0.4
Everything else is 0.
"""

READS = ()

PRIMITIVES = {"int", "char", "double", "float", "long", "short", "byte", "boolean",
              "void", "string", "bool", "unsigned", "signed"}
CLASSES = set("""String List Map Set Integer Object Class Vector Matcher JSONObject
StringBuffer Iterator Criteria UUID BigDecimal Character Boolean Double Long Float Date
Scanner ArrayList HashMap Optional Stream Collection Array Node ListNode Result Account
Game Location Exception Path File Connection ByteBuffer BufferedReader Console ItemStack
LinkedList Span Expression Query Button EditText Mongo View HashSet Entity Texture
MenuItem Cookie DataTable Color Bundle IOException ResultSet Response""".split())
TYPES = PRIMITIVES | CLASSES
MODIFIERS = {"private", "public", "protected", "static", "final", "const", "volatile"}
STRONG_START = {"final", "private", "const", "{", ";"}
BLOCK_END = {";", "{", "}"}
NOT_A_DECLARATION = {"new", "=", "return", ".", "instanceof", "extends", "implements", "throw"}
TYPE_CONTINUATION = {"<", ">", ",", "[]", "[", "]", "*", "?", "&", "::", "<>"}
CODE_LINE_END = (";", "{", "}", ")", "*/")


def previous_token(raw):
    """The last non-blank token before the newest one, and whether a newline lies in between."""
    j, newline = len(raw) - 2, False
    while j >= 0 and raw[j].strip() == "":
        newline = newline or "\n" in raw[j]
        j -= 1
    if j < 0:
        return "", True
    return raw[j].strip(), newline or "\n" in raw[j]


def previous_line_is_code(raw):
    """Whether the last non-blank token before the newest one ends a line of code."""
    for i in range(len(raw) - 2, max(-1, len(raw) - 60), -1):
        if raw[i].strip():
            return raw[i].strip().endswith(CODE_LINE_END)
    return False


def step(carry, prefix, upstream):
    raw = prefix.token_strings
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = False  # a new document: no type is open
    in_type = bool(carry)
    tok = raw[-1].strip()
    core = tok.lstrip("<([*&!~")
