    prev, newline = previous_token(raw)
    listed = core in TYPES or core.endswith("_t")  # C typedefs such as size_t
    if not listed and not core[:1].isupper():
        return False, 0.0
    if prev in NOT_A_DECLARATION:
        return False, 0.0
    at_start = newline or prev in MODIFIERS or prev in BLOCK_END
    if listed:
        if prev in STRONG_START:
            return True, -4.0
        if at_start:
            return True, -2.2
        if prev in {"(", ","}:
            return True, -1.6
        return True, -0.3
    # a capitalised word not on the list: only where a statement starts in code
    if at_start and previous_line_is_code(raw):
        return True, -0.4
    return False, 0.0

