"""Spelling responses at the join of Latin-letter word pieces.

The strongest negative response is a split x + on (tax-on, ax-on).
Other negative joins include c/x + ie, hard-c clusters + on/ade,
and x-bearing words ending in -on.  Some c + io/ian joins respond
positively. These are spelling rules, not a pronunciation dictionary.
A few whole-token spellings (xon/cox/cyan families) are also recognized.
Unmatched tokens, including weak irregular responses, are assigned zero.
"""
import re

READS = ()


def spelling_response(previous, token):
    s = token.lower()
    p = previous.lower()
    # Only join letters when the tokenizer has not inserted a word boundary.
    join = s[:1].isalpha() and p[-1:].isalpha()
    # A change from lower to title case usually starts a new identifier word.
    if token[:1].isupper() and previous[-1:].islower() and not token.isupper():
        join = False
    m = re.search(r'[^\W\d_]+$', p) if join else None
    p = m.group() if m else ''
    if p.endswith('x'):
        if s == 'on':
            return -7.0
        if s == 'xon':
            return -3.0
        if s in ('ons', 'onal', 'ion', 'ions'):
            return -2.0 if len(p) == 1 else -4.0
        if s == 'ie':
            return -4.0
        if s.startswith(('one', 'ony')):
            return -1.5
        if s == 'eon':
            return -3.0
    if p:
        if s in ('on', 'ons', 'onal'):
            if re.fullmatch(r'ca[lp]|cod|cl', p):
                if s == 'on':
                    return -8.3 if p == 'cod' else -6.0
                return -2.7
            if p.endswith('col'):
                return -1.5
            if len(p) <= 4 and 'c' in p:
                return -0.6
        if s in ('ade', 'ades'):
            if p.endswith('cl'):
                return -6.5
            if p.endswith('c'):
                return -1.1
        if p.endswith('c'):
            if s == 'ie':
                if p == 'c':
                    return -5.5
                if p.endswith(('ac', 'uc')):
                    return -5.0
                return 0.0 if p.endswith(('ic', 'yc')) else -2.2
            if s == 'ies':
                return -1.5
            if s == 'ox':
                return -4.6
            if s == 'io':
                if p == 'c':
                    return 4.2
                return 0.5 if p.endswith(('ic', 'rc', 'nc', 'lc')) else 2.2
            if s == 'ian':
                # The regular occupational -ician suffix is largely inactive.
                return 0.0 if p.endswith('ic') else 2.5
            if s == 'iao':
                return 3.9
            if s == 'ion':
                return -5.5 if p.endswith('sc') else -0.5
            if s == 'ensor':
                return 3.9
            if s == 'epend':
                return 2.5
            if s.startswith('yan'):
                return 2.7
        if s == 'xon' and re.search('[cx]', p[-3:]):
            return -3.3
        if s == 'ex' and 'c' in p[-3:]:
            return -3.8
        if s in ('x', 'xs') and p.endswith(('co', 'doc')):
            return -3.5
    word = s.strip()
    if re.fullmatch(r'[a-z]{1,3}x(?:on|ion)', word):
        return -3.0
    if word == 'cyan':
        return 2.4
    if word == 'cox':
        return -2.3
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    previous = ''
    if t and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    return None, spelling_response(previous, prefix.token_strings[-1])

"""Approximate several separate lexical response families, not one semantic rule.

English resource/material phrases and selected names give positive pulses;
real-world/life and wind-farm compounds give negative ones. Additional rules
cover R-containing consonant initialisms, selected Chinese land/energy and
human compounds, and paired middle dots. Coefficients summarize training
responses; other activation is omitted. Only the previous token is remembered,
and it is forgotten at document boundaries.
