import re
from functools import lru_cache
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=16384)
def simplified(text):
    return _SIMPLIFY.convert(text)


@lru_cache(maxsize=16384)
def consonant_cluster(previous, token):
    """Consonant-only abbreviations: strongest on an R--M/G/B junction."""
    word = token.strip()
    if not re.fullmatch('[A-Za-z]{1,6}', word):
        return 0.0
    consonants = 'bcdfghjklmnpqrstvwxz'
    tail = re.search('[A-Za-z]+$', previous) if not token[0].isspace() else None
    before = tail[0] if tail else ''
    run = before + word
    if len(run) < 3 or any(c.lower() not in consonants for c in run):
        return 0.0
    if before.lower().endswith('r'):
        following = word[0].lower()
        if run.isupper():
            if following == 'm':
                return 4.0
            if following == 'g':
                return 2.8
            if following in 'brw':
                return 1.8
            return 0.8 if following in 'cfhknvx' else 0.15
        if run.islower():
            return {'b': 1.4, 'c': 0.9, 'j': 1.2, 'n': 0.5}.get(following, 0.1)
        return {'b': 1.8, 'm': 1.0}.get(following, 0.15)
    # Common technical initialisms and the random-number-generator variable.
    if run in ('CRM', 'NMR'):
        return 2.0 if run == 'CRM' else 1.4
    if word.lower() == 'rng':
        return 1.3
    if before and word.lower().startswith('r') and len(word) > 1:
        following = word[1].lower()
        if following in 'bm':
            return 1.8
        if following == 'c':
