"""Approximate an opening-context pulse, rather than word-specific fluctuations.

The opening pulse is stronger for Cyrillic and horizontal whitespace, and
weak for Han text. Familiar English forms get a larger pulse. Identical
opening tokens retain it; a document-initial 'Title:' has its own large pulse.
Away from the opening, English word commonness supplies only a tiny bias.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def english_frequency(text):
    word = text.strip()
    if word.isascii() and word.isalpha():
        return zipf_frequency(word.lower(), 'en')
    return None


@lru_cache(maxsize=16384)
def opening_value(text):
    word = text.strip()
    if text.isspace():
        return 0.28 if '\n' in text or '\r' in text else 0.72
    if text.startswith('<|'):
        return 0.47
    if regex.search(r'\p{Script=Cyrillic}', text):
        return 0.86
    if regex.search(r'\p{Script=Han}', text):
        return 0.01
    if regex.search(r'[\p{Hiragana}\p{Katakana}\p{Hangul}]', text):
        return 0.20
    if '\ufffd' in text:
        return 0.17
    if word.isdecimal():
        return 0.43
    if word.isascii() and word.isalpha():
        frequency = english_frequency(text)
        return (0.27 + 0.04 * max(0, frequency - 4)
                + 0.16 * max(0, frequency - 6))
    if not any(c.isalnum() for c in word):
        return 0.22 if any(c in '()[]{}' for c in word) else 0.33
    return 0.38


