        opening_id, opening_text, identical, position = token, text, True, 0
    else:
        _, opening_id, opening_text, identical, position = carry
        identical = identical and token == opening_id
        position += 1
    state = document, opening_id, opening_text, identical, position
    if position == 1 and opening_text == 'Title' and text == ':':
        return state, 3.54
    if identical:
