"""Written xin/shin-like syllables, especially 新 ('new').

Separate 新 tokens give a large response; fused words give less.
A preceding classifier weakens it; 'most/all' intensifiers strengthen it. Korean
신 and short Latin spellings also respond, including syllables completed
across a token boundary. Mandarin near-rhymes have smaller responses.
Document starts have a small negative offset. A document-opening
Title: label is strongly negative at the colon.
"""
from functools import lru_cache
import re
import regex
from pypinyin import lazy_pinyin

READS = ()

# Mean responses of nearby Mandarin syllables, not a character lookup.
NEAR_RHYMES = {
    'xin': 0.6,
    'xun': 0.3,
    'zhen': 0.4,
    'sen': 0.3,
    'jin': 0.3,
    'yin': 0.15,
}


@lru_cache(maxsize=8192)
def written_response(token):
    s = token.strip()
    if s == '新':
        return 5.2 if token[:1].isspace() else 7.1
    if '新' in s:
        if s in ('最新', '的新'):
            return 4.3
        if s in ('新的', '新人', '全新'):
            return 2.4
        if s == '重新':
            return 0.2
        return 1.5 if s.endswith('新') else 0.6
    if s == '신':
        return 6.1 if token[:1].isspace() else 3.2
    if regex.fullmatch(r'\p{Script=Han}', s):
        return NEAR_RHYMES.get(lazy_pinyin(s)[0], 0.0)
    return 0.0


def latin_response(token, previous):
    s = token.strip()
    lower = s.lower()
    if lower not in ('in', 'hin', 'xin', 'shin', 'sin', 'tin', 'jin'):
        return 0.0
    separated = token[:1].isspace()
    if lower == 'xin':
        if separated:
            return 4.5
        return 6.5 if regex.search(r'\p{Script=Han}$', previous) else 0.0
    if lower == 'shin':
        return 2.5
    if lower == 'tin' and separated:
        return 1.9 if s[0].isupper() else 0.9
    if lower in ('sin', 'jin') and separated:
        return 0.8 if s[0].isupper() else 0.0
    if separated or lower not in ('in', 'hin'):
        return 0.0
    word = re.search('[a-z]+$', previous.lower() + lower).group()
    if word.endswith('xin'):
        return 7.0 if word == 'xin' else 3.4
    if word.endswith('shin'):
        return 4.1 if lower == 'in' else 3.4
    if lower == 'hin' or word.endswith(('hin', 'sin', 'yin')):
        return 0.8
    if word == 'tin':
        return 3.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    position = 0 if first else carry[2] + 1
    token = prefix.token_strings[-1]
    value = written_response(token) + latin_response(token, previous)
    if token.strip() == '新':
        if previous.endswith(('个', '個')):  # classifier: 'a new ...'
            value -= 3.0
        elif previous.endswith(('最', '全')):  # latest / entirely new
            value += 2.0
    if first:
        value -= 1.13 if token == 'Title' else 0.23
    if position == 1 and previous == 'Title' and token == ':':
        value = -5.39
    return (doc, (previous + token)[-12:], position), value

