CONNECTIVES = {
    'aber': 'de', 'doch': 'de', 'denn': 'de',
    'mais': 'fr', 'cependant': 'fr', 'pourtant': 'fr',
    'pero': 'es', 'mas': 'pt', 'ma': 'it', 'però': 'it',
    'tuttavia': 'it', 'maar': 'nl', 'men': 'da',
