    if '\n' in s:
        return -6.0 if '.' in s or '//' in s else -2.4
    for script, value in [('Han', -0.16), ('Katakana', -5.5),
                          ('Hiragana', -2.2), ('Cyrillic', -3.65),
                          ('Arabic', -4.0), ('Hangul', -2.0)]:
