from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
GREETINGS = set('hello hi hey welcome greetings'.split())
# The last three strings are the pre-apostrophe stems of do-negations.
AUXILIARIES = set('can could may might must shall should will would '
                  'do does did don doesn didn'.split())
DECLARATIONS = set('class def function public private protected package using '
                   'import from namespace typedef include const var let'.split())


@lru_cache(maxsize=8192)
def initial_pulse(token):
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    if token.startswith('<|'):
        return 0.53
    if not word:
        return -0.67
    if word.isdigit():
        return -0.31
    if lower in GREETINGS:
        return 0.0 if spaced else 6.23
    if lower in AUXILIARIES:
        return -2.48 if spaced else -5.77
    if not spaced and lower in DECLARATIONS:
        return 2.33
    if set(word) == {'·'}:
        return 5.71
    if not any(c.isalpha() for c in word):
        return 0.25
    if spaced:
        return -0.67 if zipf_frequency(lower, 'en') >= 5 else 0.0
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 2.29
    if regex.search(r'\p{Script=Han}', word):
        return 0.13
    if not word.isascii():
        return 1.88
    if len(word) == 1:
        return -0.13
    frequency = zipf_frequency(lower, 'en')
    if frequency >= 7:
        return -0.53
    if frequency >= 6:
        return 0.60
    if frequency == 0:
        return -0.82 if word.isalpha() else 0.32
    if word.isupper():
        return 2.76
    if word.istitle():
        return 1.73 if frequency >= 5 else 2.30
    return 1.38 if frequency >= 5 else 0.70


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        value = initial_pulse(prefix.token_strings[-1])
        return (doc, token, value, True), value
    _, first, pulse, repeating = carry
    repeating = repeating and token == first
    return (doc, first, pulse, repeating), pulse if repeating else 0.0

