"""Layer 1 MLP down-projection, component 5627: a "document-opening word" feature.

What it does, in plain terms: the component is almost silent inside a document. It
responds at the first token of each document (the token right after <|endoftext|>, or the
first token of a packed row), and there its size depends on which kind of word the
document opens with:

  * a code header (#include, package, using, import) or a capitalised word or all-caps
    word such as a name, title or greeting (no leading space) -> positive, the largest
    for all-caps and headline-like words;
  * a modal or instruction verb (Can, Would, Do, Use, Thank) -> strongly negative;
  * a function word (the, a, of, in, is), a lower-case word with a leading space,
    whitespace, a digit, or a comment marker (#, //) -> mildly negative;
  * a single capital letter, other punctuation, or a lower-case word without a leading
    space -> about zero to mildly positive;
  * other scripts (Cyrillic, CJK, Thai, ...) -> mildly positive.

Each class's value is the mean activation of its tokens at document starts in the
training data, weighted by how often each token opens a document. Everywhere else
(mid-document positions) the program predicts 0, which is close to the component's
typical near-zero activation there.

What it does not capture: the within-class spread is large (one word can differ by
several units), so this version explains only a modest share of the variance at document
starts. A per-token table of document-opening words would explain most of it, but it
would be a list of token ids with no concept behind it, so it is not used here.
"""

READS = ()

# Modal and auxiliary verbs, and imperative verbs that open a sentence.
MODALS = set(
    "can could would will should shall may might must do does did don use thank require".split()
)
# Common English function words, as they open a document (lower-cased).
FUNCTION_WORDS = set(
    "the a an of to in and is for on it that with as be by or at from this are was were "
    "not but if so its their they he she we you i there here which who what when where".split()
)
# Code keywords that open a source file.
CODE_HEADERS = {"#include", "package", "using", "import", "namespace"}


def _opens_document(prefix) -> bool:
    """True at the row's first token and wherever the document id changes, the points where
    the model resets its attention."""
    ids = prefix.document_ids
    return len(ids) == 1 or ids[-1] != ids[-2]


def _value(token: str) -> float:
    """The activation a document-opening token is given, by the class it belongs to."""
    word = token.strip()
    if token in CODE_HEADERS:
        return 3.0
    if not word:
        return -0.6
    if word.isdigit():
        return -0.3
    if word.isascii() and word.isalpha():
        if word.lower() in MODALS:
            return -3.0
        if word.lower() in FUNCTION_WORDS:
            return -0.5
        if word.isupper() and len(word) > 1:
            return 2.1
        if word[0].isupper():
            if len(word) == 1:
                return 0.1
            return 0.4 if token.startswith(" ") else 2.0
        return -0.4 if token.startswith(" ") else 0.5
    if word.startswith(("#", "//", "/*")):
        return -0.3
    if not word.isascii() and any(ch.isalpha() for ch in word):
        return 1.1
    return 0.4


def step(carry, prefix, upstream):
    """This component's activation at the last token of `prefix`."""
    if not _opens_document(prefix):
        return carry, 0.0
    return carry, float(_value(prefix.token_strings[-1]))

