"""Detect the leftover tail of a repeated decorative character.

Small punctuation tokens continuing a long rule/comment border get a
negative signal; large chunks starting the rule do not. The magnitude
falls with the tail's length. Nonbreaking-space padding, escaped repeated
punctuation, and emoji presentation selectors have separate small rules.
This captures negative formatting responses, not isolated word-pair spikes.
"""
import math

READS = ()
# Character: (strength, decay with tail length, preceding-run scale,
#             multipliers for a line ending and a blank line).
PARAMETERS = {
    '*': (7.82, 0.14, 4.0, 0.64, 0.1),
    '=': (9.15, 0.3, 2.0, 0.32, 0.1),
    '-': (7.18, 0.18, 12.0, 0.55, 0.16),
    '_': (5.9, 0.18, 2.0, 0.59, 0.31),
    '#': (9.57, 0.26, 12.0, 0.68, 0.23),
    '/': (8.0, 0.15, 4.0, 0.6, 0.1),
    '~': (5.62, 0.32, 4.0, 0.44, 0.19),
    '^': (6.35, 0.4, 3.0, 0.6, 0.1),
    '+': (6.0, 0.2, 4.0, 0.6, 0.1),
    '.': (4.97, 0.12, 8.0, 0.11, 0.1),
    '%': (3.0, 0.3, 4.0, 0.6, 0.1),
    '>': (4.0, 0.3, 4.0, 0.6, 0.1),
    '\\': (1.0, 0.2, 4.0, 0.6, 0.1),
    '!': (4.0, 0.3, 4.0, 0.2, 0.1),
    '?': (4.0, 0.3, 4.0, 0.2, 0.1),
    ':': (2.0, 0.3, 4.0, 0.4, 0.1),
    ';': (1.2, 0.3, 4.0, 0.4, 0.1),
    '|': (5.0, 0.3, 4.0, 0.6, 0.1),
    '¯': (4.0, 0.3, 4.0, 0.6, 0.1),
    '·': (2.0, 0.3, 4.0, 0.6, 0.1),
}


def normalize(s):
    return s.replace('…', '...').replace('—', '--').replace('–', '-')


def predict(prev, s):
    if s == '\ufe0f':
        return -3.2 if prev.strip() in {'❤', '➡'} else -1.2
    if prev == '\\t' and s == '\\':
        return -.65
    if len(prev) >= 2 and prev[-1] == '\\' and s == prev[-2]:
        if s in PARAMETERS:
            return -1.6

    # Repeated nonbreaking-space padding, possibly alternating with spaces.
    if '\xa0' in prev and not prev.strip(' \xa0'):
        n = prev.count('\xa0')
        if s == ' ' or (s and not s.strip('\r\n')):
            return -.7 * n if ' ' in prev else 0.0
        if '\xa0' in s and not s.strip(' \xa0'):
            m = s.count('\xa0')
            if ' ' in s and ' ' in prev and n >= 2:
                return -(1.1 + .6 * n) * math.exp(-.65 * (m - 1))
            if ' ' not in s and ' ' not in prev and m <= n:
                if m == 1 and n >= 2:
                    # Single leftovers after binary-sized padding chunks.
                    if n in (4, 8):
                        return -(1.5 + .5 * n)
                    return -.7 if n == 2 else -1.4
                if n >= 4:
                    value = -(.2 + 3.5 * max(0.0, 1.0 - m / 8.0))
                    return .7 * value if m == 4 else value
        return 0.0

    prev, s = normalize(prev), normalize(s)
    if not prev or prev[-1] not in PARAMETERS:
        return 0.0
    c = prev[-1]
    n = len(prev) - len(prev.rstrip(c))
    if s and not s.strip('\r\n') and n >= 8:
        strength = 2.5 if c == '/' else 1.2
        return -strength * (.2 if s.count('\n') > 1 else 1.0)
    if not s.startswith(c):
        return 0.0
    m = len(s) - len(s.lstrip(c))
    rest = s[m:]
    if rest.strip('\r\n') not in ('', '\\'):
        return 0.0
    if n < 2 or not (m < n or (c in '~^' and m <= n)):
        return 0.0
    gain, decay, scale, line_end, blank_line = PARAMETERS[c]
    value = -gain * math.exp(-decay * (m - 1)) * min(1.0, n / scale)
    if rest.count('\n') > 1:
        return value * blank_line
    return value * line_end if '\n' in rest or rest == '\\' else value


def step(carry, prefix, upstream):
    if (len(prefix.token_ids) < 2
            or prefix.document_ids[-1] != prefix.document_ids[-2]):
        return None, 0.0
    return None, predict(prefix.token_strings[-2], prefix.token_strings[-1])

