        return 1.25
    if s and set(s) == {'^'}:
        return -1.38
    if s == '\r':
        return -1.61
    if s.startswith('//'):
        return -0.88
    if s.startswith('/*'):
        return -0.16
    if s.startswith('('):
        return -0.48
    if s.startswith(('<', '[', '{')):
        return -0.20
    if s == '#':
        return -0.32
    if s.startswith('##'):
        return 0.08
    if s == '•':
        return 0.85
    if s.isnumeric():
        return 0.33
    if regex.search(r'\p{Script=Han}', s):
        return 0.19
    if s == '\t':
        return 0.78
    if s.isspace():
        return 0.20 if '\n' in s else 0.06
    if s in (',', '.', ')', ';', '|'):
        return 0.25
    if s.isascii() and s.isupper():
        return 0.30 if len(s) == 1 else 0.04
    return 0.04


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, 1, s, True), opening_value(s)
    _, position, first, repeated = carry
    repeated = repeated and s == first
    if repeated and (first == '\r' or set(first) == {'^'}):
        value = opening_value(first)
    elif position == 1 and first == 'public' and s == ' class':
        value = 0.29
    elif position == 1 and first == 'Title' and s == ':':
        value = -1.50
    elif s == '··':
        value = -0.41
    else:
        value = 0.0
    return (doc, position + 1, first, repeated), value

"""Detect standalone space tokens, often introducing a number.

Month names, quantity cues and reference abbreviations strengthen the response.
Indentation, digits and operators weaken it. Dense standalone-space formatting
also weakens it. Other tokens are approximated by zero; document boundaries
reset the short history and the spacing count.
"""
import calendar
import re
from collections import deque

READS = ()
MONTHS = {s.lower() for s in (*calendar.month_name, *calendar.month_abbr) if s}
MONTHS.add('sept')
WEEKDAYS = {s.lower() for s in (*calendar.day_name, *calendar.day_abbr)}
QUANTITY_CUES = set(
    'about around approximately roughly nearly over under than between '
    'since until before after'.split()
)
PREPOSITIONS = set('in on at of for from with'.split())
FUNCTION_WORDS = set('and or but so be is are was were to a an'.split())
REFERENCES = set(
    'fig figure figs figures table tables section chapter page pages line lines '
    'no nr vol volume cap art pp p cf ref equation eq clause appendix app '
    'theorem lemma example step claim claims'.split()
)
REFERENCE_ABBREVIATIONS = set('no nr vol cap art pp p cf ref eq app sec'.split())
OPERATORS = set('=+-*/<>|&^~')


def period_value(last_word):
    """Distinguish numbered references from sentence-ending full stops."""
    stem = last_word[:-1].strip('([{"\'')
    if stem.lower() in MONTHS:
        return 2.2
    if re.fullmatch(r'(?:[A-Za-z]{1,3}\.){2,}', last_word):
        return 2.25
    if stem.lower() in REFERENCE_ABBREVIATIONS:
        return 1.9
    if stem.lower() in {'fig', 'figs'}:
        return 1.2
    if len(stem) == 1 and stem.isupper():
        return 1.2
    if any(c.isdigit() for c in stem):
        return 0.2
    return 0.5


def space_value(previous, density):
    if not previous:
        return 0.2
    token = previous[-1]
    word = token.strip()
    lower = word.lower()
    if not word:
        return 0.02 if '\n' in token else -0.02
    if token.endswith('\n'):
        return 0.0
    last_word = ''.join(previous).split()[-1].lstrip('([{"\'')
    if last_word.endswith('\\n'):
        value = -0.2
    elif word == '.':
        value = period_value(last_word)
    elif word.isalpha():
        value = 0.74 + 0.12 * word[0].isupper()
        if lower in MONTHS:
            value += 1.01
        elif lower in WEEKDAYS:
            value += 0.4
        elif lower in QUANTITY_CUES:
            value += 0.37
        elif lower in PREPOSITIONS:
            value += 0.37
        elif lower in FUNCTION_WORDS:
            value -= 0.06
        elif lower in REFERENCES:
            value += 0.23
    elif word[-1].isdigit():
        value = 0.14
    elif word.endswith(','):
        value = 0.8
    elif word.endswith(':'):
        value = 0.65
    elif word == ';':
        value = 0.52
    elif word in {'§', '§§'}:
        value = 1.5
    elif word in {'–', '—'}:
        value = 0.6
    elif re.search(r"['’](s|d|ll|re|ve|m|t)$", last_word):
        value = 0.95
    elif all(c in OPERATORS for c in word):
        value = 0.24
    elif word[0] in '[{(':
        value = 0.23
    else:
        value = 0.47
    return value - 2.65 * density


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, window, count = (), deque(maxlen=128), 0
    else:
        _, previous, window, count = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token == ' ':
        value = space_value(previous, count / max(1, len(window)))
    if len(window) == window.maxlen:
        count -= window[0]
    is_space = token == ' '
    window.append(is_space)
    count += is_space
    return (doc, (*previous[-7:], token), window, count), value

programs.haiku:
"""Fires on a bare space token that sits right before a number.

The space is its own token in this tokenizer (digits are single tokens), so the model
must decide at the space that a number comes next. The component's output is largest
after a month name (\"December \" -> a day), then after words and punctuation that
introduce dates, years, quantities and references (\"in \", \"line \", \"§ \", \"June 5, \").
"""

MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December", "Jan", "Feb", "Aug", "Sep",
          "Sept", "Oct", "Nov", "Dec"}
# words after which a number usually comes next: dates, years, quantities, figure/line references
NUMBER_INTRO = {"in", "In", "on", "at", "about", "over", "from", "for", "than", "between",
                "around", "since", "after", "under", "until", "approximately", "least",
                "only", "first", "line", "Line", "Lines", "section", "Section", "Figure",
                "Table", "born", "Article"}
# symbols that come right before a number: section and degree signs, numero
NUMBER_SYMBOLS = {"§", "§§", "°", "№"}

READS = ()

def step(carry, prefix, upstream):
    since = 99 if carry is None else carry
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        since = 99
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = prev.strip()
    value = 0.0
    if tok == " ":
        if word in MONTHS:
            value = 1.9
        elif word in NUMBER_INTRO or word in NUMBER_SYMBOLS:
            value = 1.1
        elif prev == ".":
            value = 1.1
        elif prev == ",":
            value = 1.6 if since <= 6 else 0.7   # "June 5, " inside a date
        elif prev in (":", ";", ")", "),", ".,", "'s"):
            value = 0.6
        elif word.isalpha():
            value = 0.7
        elif word == "" or word.isdigit() or "\n" in prev:
            value = -0.1
    new_since = 0 if word in MONTHS else min(since + 1, 99)
    return new_since, float(value)
